// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Makroekonomi: milli gelir, büyüme, işsizlik (orta).
const ozEconomics8Orta = <(String, String, List<String>, String)>[
  ('Bir mobilya fabrikası 2023\'te ürettiği 200 koltuğun 50\'sini yıl sonuna kadar satamamış ve depoda tutmuştur. Bu 50 koltuk ulusal hesaplarda nasıl ele alınır?', '2023 GSYH\'sine stok değişimi olarak yatırım kaleminde eklenir', ['Satılacakları yılın GSYH\'sine hanehalkı tüketimi olarak eklenir', 'Hiçbir yılın GSYH\'sine eklenmez', '2023 GSYH\'sine kamu harcaması olarak eklenir'], 'GSYH üretimin yapıldığı dönemi esas alır. Satılmayan ürünler, stok artışı olarak firmanın kendine yaptığı yatırım sayılır ve üretildikleri yılın GSYH\'sine girer.'),
  ('Kendi evinde oturan bir ev sahibinin, evin sağladığı barınma hizmeti için ulusal hesaplarda nasıl bir işlem yapılır?', 'Evin piyasada getireceği kira tahmin edilerek GSYH\'ye eklenir', ['Ev sahibine kira ödenmediği için hiçbir değer eklenmez', 'Evin güncel satış değeri her yıl yeniden hesaplanarak GSYH\'ye eklenir', 'Yalnızca evin emlak vergisi GSYH\'ye eklenir'], 'Ulusal hesaplarda ev sahiplerinin kendi konutları için emsal (tahmini) kira hesaplanır. Böylece kiracı ile ev sahibi arasındaki ayrım GSYH\'yi yapay biçimde değiştirmez.'),
  ('Bir ressamın 1950\'de yaptığı tablo 2024\'te bir müzayedede 1 milyon liraya satılmış, müzayede evi satış bedelinin yüzde 10\'unu komisyon olarak almıştır. 2024 GSYH\'sine bu işlemden ne kadar eklenir?', '100 bin lira', ['1 milyon lira', '1,1 milyon lira', 'Hiçbir tutar eklenmez'], 'Tablo 2024\'te üretilmediği için satış bedeli GSYH\'ye girmez. Ancak müzayede evinin 2024\'te verdiği aracılık hizmetinin karşılığı olan komisyon cari üretimdir.'),
  ('Bir değirmenin ürettiği un, bir fırına satıldığında ara mal sayılır. Aynı un bir hanehalkına evde ekmek yapması için satılırsa ulusal hesaplarda nasıl sınıflanır?', 'Nihai mal sayılır ve tüketim harcamasına girer', ['Yine ara mal sayılır ve hiçbir koşulda GSYH\'ye girmez', 'Yatırım malı sayılır', 'Kamu harcaması olarak sınıflanır'], 'Bir malın ara mal mı nihai mal mı olduğu niteliğine değil kullanımına bağlıdır. Son kullanıcı olan hanehalkının aldığı un nihai maldır.'),
  ('Bir tüketici yurt dışında üretilmiş bir otomobili 1 milyon liraya satın alıyor. Harcama yöntemine göre bu işlemin GSYH\'ye net etkisi nedir? (Satıcının yurt içinde yarattığı aracılık hizmeti yok sayılmaktadır.)', 'Sıfırdır; tüketim artışı ithalatla dengelenir', ['GSYH 1 milyon lira artar', 'GSYH 1 milyon lira azalır', 'GSYH 2 milyon lira artar; hem tüketim hem ithalat eklenir'], 'Otomobil tüketim (C) kalemine eklenir ama yurt içinde üretilmediği için ithalat (M) olarak düşülür. Böylece yurt içi üretimi ölçen GSYH değişmez.'),
  ('Devlet okullarında çalışan öğretmenlerin verdiği eğitim hizmeti piyasada satılmadığı hâlde GSYH\'ye hangi değerle eklenir?', 'Üretim maliyetiyle, başta öğretmen maaşları olmak üzere', ['Öğrencilerin bir özel okula ödeyecekleri tahmini ücretlerle', 'Hiçbir değerle eklenmez', 'Okul binalarının piyasa değeriyle'], 'Kamu hizmetlerinin piyasa fiyatı olmadığından ulusal hesaplarda bu hizmetler girdi maliyetiyle, yani ücretler ve kullanılan malzemelerle değerlenir.'),
  ('Bir ülkede bir yıl içindeki toplam yurt içi harcama (tüketim, yatırım ve kamu harcaması toplamı) 5 trilyon lira, GSYH ise 4,6 trilyon liradır. Bu durum en iyi nasıl açıklanır?', 'Net ihracat 0,4 trilyon lira açık vermiştir', ['Net ihracat 0,4 trilyon lira fazla vermiştir', 'Stoklar 0,4 trilyon lira azalmıştır', 'Amortisman 0,4 trilyon lira olmuştur'], 'GSYH = C + I + G + (X − M) olduğuna göre 4,6 = 5 + NX ve NX = −0,4 trilyon lira olur. Yurt içi harcamanın üretimi aşan kısmı ithalatla karşılanmıştır.'),
  ('Bir ülkenin GSYH\'sini üretim yöntemiyle hesaplamanın, harcama yöntemine göre sağladığı en belirgin bilgi hangisidir?', 'Üretimin tarım, sanayi ve hizmetler gibi sektörlere dağılımı', ['Hanehalklarının tasarruf oranı', 'Dış ticaret açığının büyüklüğü ve hangi ülkelerle verildiği', 'Ücretlerin milli gelirdeki payı'], 'Üretim yöntemi her sektörün yarattığı katma değeri ayrı ayrı topladığı için ekonominin sektörel yapısını doğrudan gösterir.'),
  ('Bir otomobil fabrikası yıl içinde 900 milyon liralık otomobil satmış; bunun için 500 milyon liralık parça, 100 milyon liralık enerji satın almış ve 200 milyon lira ücret ödemiştir. Fabrikanın katma değeri kaç milyon liradır?', '300', ['100', '400', '700'], 'Katma değer, satış değerinden satın alınan ara girdiler (parça ve enerji) çıkarılarak bulunur: 900 − 500 − 100 = 300. Ücretler ara girdi değildir; katma değerin bir parçasıdır.'),
  ('Katma değer hesabında bir firmanın çalışanlarına ödediği ücretler için hangisi doğrudur?', 'Katma değerin içinde yer alır, satıştan düşülmez', ['Ara girdi gibi satış değerinden düşülerek hesaptan çıkarılır', 'Katma değere iki kez eklenir', 'Yalnız kamu firmalarında hesaba katılır'], 'Katma değer, firmanın ürettiği değerden başka firmalardan alınan girdiler çıkarılarak bulunur. Bu değer ücret, faiz, rant ve kâr olarak üretim faktörlerine dağıtılır.'),
  ('Bir ülkenin bir çeyrekteki GSYH\'si önceki çeyreğe göre karşılaştırılırken neden mevsim ve takvim etkilerinden arındırılmış seriler kullanılır?', 'Tatiller ve hava koşulları gibi düzenli dalgalanmaların gerçek eğilimi gizlememesi için', ['Arındırılmış seriler her zaman daha yüksek büyüme oranı gösterdiği ve olumlu algı yarattığı için', 'Ham veriler yalnızca yılda bir kez yayımlandığı için', 'Fiyat değişimlerinin etkisini ortadan kaldırmak için'], 'Örneğin tarım ve turizm bazı çeyreklerde düzenli olarak yükselir. Mevsimsellikten arındırma, ardışık çeyreklerin karşılaştırılmasını anlamlı kılar. Fiyat etkisini ise reel hesaplama giderir.'),
  ('GSYH\'yi harcama, üretim ve gelir yöntemleriyle hesaplamak ilke olarak aynı sonucu verir. Bunun temel nedeni hangisidir?', 'Bir kişinin yaptığı her harcama başka birinin geliri olur', ['Üç yöntem de yalnızca tüketimi ölçer', 'Devlet sonuçları eşitlemek için düzeltme yapmak zorundadır', 'Üç yöntem de aynı vergi kayıtlarını kullanır'], 'Satın alınan her nihai malın bedeli, üretimine katılanlar arasında ücret, faiz, rant ve kâr olarak paylaşılır. Bu yüzden toplam harcama, toplam üretim ve toplam gelir eşittir; uygulamadaki farklar istatistiksel tutarsızlıktır.'),
  ('Bir ülkede milli gelirin içinde ücretlerin payının yıllar içinde düşüp kârların payının artması hangi gelir dağılımı türündeki değişmeyi gösterir?', 'Fonksiyonel gelir dağılımı', ['Kişisel gelir dağılımı', 'Bölgesel gelir dağılımı', 'Sektörel istihdam ve üretim dağılımı'], 'Fonksiyonel (faktörel) gelir dağılımı, milli gelirin ücret, kâr, faiz ve rant gibi üretim faktörleri arasında nasıl paylaşıldığını gösterir. Kişisel dağılım ise hanehalkları arasındaki paylaşımı inceler.'),
  ('Bir ekonomide GSMH 1.000, amortisman 100, dolaylı vergiler 90 ve sübvansiyonlar 10 milyar liradır. Faktör maliyetiyle milli gelir kaç milyar liradır?', '820', ['800', '900', '1.000'], 'Önce net milli hasıla: 1.000 − 100 = 900. Faktör maliyetine geçmek için dolaylı vergiler çıkarılır, sübvansiyonlar eklenir: 900 − 90 + 10 = 820.'),
  ('Faktör maliyetiyle milli gelir hesaplanırken piyasa fiyatlarından dolaylı vergilerin çıkarılmasının nedeni nedir?', 'Dolaylı vergiler fiyatı artırır ama hiçbir üretim faktörünün geliri olmaz', ['Dolaylı vergiler iki kez sayılmış amortismandır', 'Dolaylı vergiler yalnızca ithal mallardan alındığı için', 'Dolaylı vergiler, hanehalklarının o yıl yaptığı tasarrufun bir ölçüsü olduğu için'], 'KDV gibi vergiler malın piyasa fiyatına eklenir; bu kısım ücret, rant, faiz ya da kâr olarak faktörlere değil devlete gider. Faktör gelirlerini bulmak için ayıklanır.'),
  ('Milli gelirden kişisel gelire geçerken aşağıdakilerden hangisi eklenir?', 'Devletin hanehalklarına yaptığı transfer ödemeleri', ['Şirketlerin ortaklarına dağıtmayıp şirkette tuttuğu kârlar', 'Kurumlar vergisi', 'Sosyal güvenlik primleri'], 'Kişisel gelir, hanehalklarının eline fiilen geçen gelirdir. Dağıtılmayan kârlar, kurumlar vergisi ve primler düşülür; emekli aylığı gibi transferler ise eklenir.'),
  ('Bir hanehalkının kişisel geliri 800 bin lira, ödediği gelir vergisi 120 bin lira ve tüketim harcaması 600 bin liradır. Bu hanehalkının tasarrufu kaç bin liradır?', '80', ['200', '120', '680'], 'Kullanılabilir gelir 800 − 120 = 680 bin liradır. Kullanılabilir gelir tüketim ve tasarrufa ayrıldığından tasarruf 680 − 600 = 80 bin liradır.'),
  ('Bir ülkede bir yılda gayrisafi yatırım 150, amortisman 180 milyar lira olmuştur. Bu durum ülkenin sermaye stoku için ne gösterir?', 'Sermaye stoku 30 milyar lira azalmıştır', ['Sermaye stoku 330 milyar lira artmıştır', 'Sermaye stoku 150 milyar lira artmış, amortisman ayrıca eklenmiştir', 'Sermaye stoku değişmemiştir'], 'Net yatırım = gayrisafi yatırım − amortisman = 150 − 180 = −30. Negatif net yatırım, yenilenenden fazla sermayenin aşındığını, yani stokun küçüldüğünü gösterir.'),
  ('Ekonomik dalgalanmalar sırasında harcama bileşenleri arasında genellikle en oynak (en çok inip çıkan) bileşen hangisidir?', 'Yatırım harcamaları', ['Hanehalkı gıda tüketimi', 'Kamu personel harcamaları', 'Hizmet tüketimi'], 'Firmalar gelecek beklentileri bozulunca yatırımları kolayca erteleyebilir; bu yüzden yatırım, durgunluklarda tüketimden çok daha sert düşer ve canlanmada hızla artar.'),
  ('Ekonomide durgunluk beklentisiyle firmaların satamadıkları malların depolarda planlanmamış biçimde birikmesi, harcama yöntemine göre o dönemin GSYH\'sini nasıl etkiler?', 'Stok yatırımı olarak GSYH\'ye girer; ölçülen üretim düşmez', ['Satılmayan mallar satılana kadar o dönemin GSYH\'sinden tamamen çıkarılır', 'Tüketim harcaması olarak GSYH\'ye girer', 'İthalat sayılarak GSYH\'den düşülür'], 'Muhasebe kimliği gereği üretilip satılmayan her mal stok artışı (yatırım) olarak kaydedilir. Planlanmamış stok birikimi ise firmaları sonraki dönemlerde üretimi kısmaya yöneltir.'),
  ('Bir ülkenin GSYH\'si 1.500 milyar lira, yurt dışına ödenen net faktör geliri 40 milyar lira ve amortisman 160 milyar liradır. Net milli hasıla kaç milyar liradır?', '1.300', ['1.380', '1.340', '1.420'], 'Yurt dışına net faktör geliri ödendiği için GSMH = 1.500 − 40 = 1.460. Net milli hasıla = 1.460 − 160 = 1.300 milyar lira.'),
  ('Basit bir ekonomide kullanılabilir gelir 500 milyar lira, kişisel gelir vergisi 100 milyar lira ve devletten alınan transferler 60 milyar liradır. Başka kalem yoksa kişisel gelir kaç milyar liradır?', '600', ['560', '440', '660'], 'Kullanılabilir gelir = kişisel gelir − doğrudan vergiler. Buradan kişisel gelir = 500 + 100 = 600 milyar liradır. Transferler kişisel gelirin içinde zaten yer alır.'),
  ('Bir ülkede GSYH deflatörü bir yılda 125\'ten 140\'a yükselmiştir. Deflatöre göre bu yılki fiyat artış oranı yüzde kaçtır?', '12', ['15', '10,7', '40'], 'Artış oranı (140 − 125) / 125 = 0,12, yani yüzde 12\'dir. Puan farkı (15) ile yüzde değişim karıştırılmamalıdır.'),
  ('Bir ülkede GSYH deflatörünün 100\'ün altında olması neyi gösterir?', 'Cari yılda fiyatlar baz yılından ortalama olarak düşüktür', ['Ekonominin reel üretimi o yıl baz yılının altına düşmüştür', 'Nüfus baz yılına göre azalmıştır', 'Ülke dış ticaret açığı vermiştir'], 'Deflatör = nominal GSYH / reel GSYH × 100\'dür. 100\'ün altında olması, cari fiyatlarla ölçülen değerin baz yılı fiyatlarıyla ölçülenden küçük, yani fiyatların daha düşük olduğunu gösterir.'),
  ('Yalnızca elma ve armut üreten bir ekonomide 2020\'de 10 kg elma 2 liradan, 5 kg armut 4 liradan; 2021\'de 12 kg elma 3 liradan, 6 kg armut 5 liradan üretilmiştir. 2020 baz yılı alınırsa 2021 reel GSYH\'si kaç liradır?', '48', ['66', '40', '56'], 'Reel GSYH 2021 miktarlarını 2020 fiyatlarıyla çarpar: 12 × 2 + 6 × 4 = 24 + 24 = 48 lira. 66 lira ise 2021\'in nominal GSYH\'sidir.'),
  ('Bir ülkede bir yıl içinde nominal GSYH yüzde 5 artarken reel GSYH yüzde 2 azalmıştır. Bu durum en iyi nasıl açıklanır?', 'Fiyatlar, üretimdeki düşüşü aşacak kadar artmıştır', ['Üretim artmış ama fiyatlar düşmüştür', 'Nüfus azaldığı için istatistik kurumu bir hesaplama hatası yapmıştır', 'Fiyatlar da üretim de değişmemiştir'], 'Nominal GSYH miktar ve fiyatın birlikte etkisidir. Reel üretim düşerken nominal değerin artması, fiyat düzeyinin yaklaşık yüzde 7 yükseldiğini gösterir.'),
  ('Satın alma gücü paritesine (SAGP) göre yapılan gelir karşılaştırmalarında temel amaç nedir?', 'Ülkeler arasındaki fiyat düzeyi farklarını gidererek gerçek yaşam standartlarını karşılaştırmak', ['Ülkelerin merkez bankalarında tuttukları döviz ve altın rezervlerinin büyüklüğünü karşılaştırmak', 'Yalnızca ihraç edilen malların değerini ölçmek', 'Ülkelerin borçlarını aynı para birimine çevirmek'], 'Aynı gelirle farklı ülkelerde farklı miktarda mal alınabilir. SAGP, aynı mal sepetinin her ülkedeki maliyetini esas alarak geliri karşılaştırılabilir kılar.'),
  ('Bir ülkede yalnızca en zengin yüzde 1\'in gelirleri büyük ölçüde artarken diğer herkesin geliri aynı kalırsa ortalama ve medyan hanehalkı geliri nasıl değişir?', 'Ortalama artar, medyan değişmez', ['İkisi de en zenginlerin gelir artışı oranında yükselir', 'Medyan artar, ortalama değişmez', 'İkisi de azalır'], 'Ortalama uç değerlerden etkilenir ve yükselir. Medyan ise ortadaki hanenin gelirini gösterdiğinden, en tepedeki değişimden etkilenmez.'),
  ('Bir sanayi bölgesinde fabrikaların kirlettiği nehri temizlemek için yapılan harcamaların GSYH\'yi artırması, GSYH\'nin hangi zayıflığına örnektir?', 'Zararları gidermeye yönelik harcamaları refah artışı gibi göstermesi', ['Devletin sunduğu kamu hizmetlerini hiçbir biçimde ölçmeyip dışarıda bırakması', 'İthal malları iki kez sayması', 'Yalnızca nominal değerleri vermesi'], 'Kirliliğin verdiği zarar GSYH\'den düşülmezken temizleme harcamaları eklenir. Böylece refahı geri getirme çabası, büyüme olarak görünür.'),
  ('Arama motorları ve çevrim içi haritalar gibi kullanıcıya ücretsiz sunulan dijital hizmetlerin GSYH\'deki durumu için hangisi doğrudur?', 'Kullanıcıya sağladıkları fayda GSYH\'ye büyük ölçüde yansımaz', ['Kullanıcı sayısıyla orantılı olarak GSYH\'ye tam piyasa değeriyle eklenir', 'Bu hizmetler ithalat sayılarak GSYH\'den düşülür', 'GSYH\'ye yalnızca kamu harcaması olarak girer'], 'Ücretsiz hizmetlerin piyasa fiyatı yoktur; GSYH\'ye ancak dolaylı olarak, örneğin reklam gelirleri üzerinden girer. Tüketicinin elde ettiği fayda ölçülmez.'),
  ('Bir ülkede on yıl boyunca elektrik tüketimi resmî GSYH\'den çok daha hızlı artmıştır. Bazı araştırmacılar bu farkı hangi olgunun büyüklüğünü tahmin etmek için kullanır?', 'Kayıt dışı ekonomi', ['Dış ticaret açığı', 'Kamu borç stoku', 'Döviz rezervleri'], 'Fiziksel girdi yönteminde elektrik tüketimi, ekonomik faaliyetin göstergesi kabul edilir. Tüketimin resmî üretimi aşan artışı kayıt dışı faaliyetlere işaret edebilir.'),
  ('TÜİK işgücü istatistiklerinde bir kişinin kayıt dışı çalıştığı hangi ölçüte göre belirlenir?', 'Yaptığı iş nedeniyle bir sosyal güvenlik kuruluşuna kayıtlı olmaması', ['Haftada 40 saatten az çalışması', 'Kamu sektörü dışında çalışması', 'Aylık olarak yasal asgari ücretin altında bir ücretle çalışıyor olması'], 'TÜİK, ana işinden dolayı herhangi bir sosyal güvenlik kuruluşuna kayıtlı olmadan çalışanları kayıt dışı istihdam olarak tanımlar.'),
  ('Dört sektörlü bir ekonomide tasarruf 200, vergiler 300, ithalat 150, yatırım 250 ve kamu harcaması 280 milyar liradır. Gelir dengesinin sağlanması için ihracat kaç milyar lira olmalıdır?', '120', ['70', '180', '50'], 'Dengede sızıntılar enjeksiyonlara eşittir: S + T + M = I + G + X. 200 + 300 + 150 = 250 + 280 + X, buradan X = 650 − 530 = 120 milyar lira.'),
  ('Döngüsel akım modelinde sızıntıların toplamı enjeksiyonların toplamını aşarsa milli gelir için ne beklenir?', 'Harcama akımı zayıflar ve gelir azalma eğilimine girer', ['Gelir hiç değişmez', 'Gelir hızla artar', 'Yalnızca fiyatlar yükselir, üretim ve istihdam hiç değişmez'], 'Akımdan çekilen para eklenenden fazlaysa firmaların satışları düşer; üretim ve gelir, sızıntılar enjeksiyonlara eşitlenene kadar azalır.'),
  ('Döngüsel akım modelinde finansal piyasaların üstlendiği temel işlev hangisidir?', 'Hanehalklarının tasarruflarını firmaların yatırımlarına aktarmak', ['Mal ve hizmetleri hanehalkları ile firmalar adına doğrudan kendisi üretmek', 'Vergileri toplamak', 'Dış ticareti yasaklamak'], 'Bankalar ve sermaye piyasaları, akımdan çekilen tasarrufları yatırım harcaması olarak akıma geri döndüren aracı kurumlardır.'),
  ('Devletin ve dış ticaretin olmadığı kapalı bir ekonomide gerçekleşen tasarruf ile gerçekleşen yatırım arasındaki muhasebe ilişkisi nedir?', 'Her zaman birbirine eşittir', ['Tasarruf daima yatırımın iki katıdır', 'Yatırım daima tasarruftan büyüktür', 'Aralarında hiçbir ilişki yoktur'], 'Bu ekonomide Y = C + I ve Y = C + S olduğundan I = S olur. Planlanmamış stok değişimleri de yatırıma dâhil edildiğinden eşitlik muhasebe olarak her zaman sağlanır.'),
  ('Açık bir ekonomide ulusal tasarruf 200 milyar lira, yurt içi yatırım 260 milyar liradır. Ulusal hesap kimliğine göre net ihracat ne olmalıdır?', '−60 milyar lira', ['60 milyar lira', '460 milyar lira', 'Sıfır, çünkü kimlik her zaman dengededir'], 'Açık ekonomide S − I = NX olur. 200 − 260 = −60. Yurt içi yatırımın tasarrufu aşan kısmı yabancı tasarrufla, yani dış açıkla finanse edilir.'),
  ('Açık bir ekonomide yurt içi yatırımlar ulusal tasarruflardan fazlaysa bu farkın kaynağı nedir?', 'Yurt dışından sağlanan tasarruflar', ['Merkez bankasının yatırım için sınırsız miktarda para basması', 'Stoklardaki azalma', 'Ücretlerin artması'], 'S − I = NX kimliğine göre yatırım tasarrufu aşınca net ihracat negatiftir; ülke harcadığından az ürettiği farkı yabancıların tasarruflarını kullanarak kapatır.'),
  ('Basit Keynesyen modelde planlanan yatırım planlanan tasarruftan küçükse aşağıdakilerden hangisi gerçekleşir?', 'Firmaların stokları planlanmadan artar ve üretim kısılır', ['Firmaların stokları azalır ve üretim artırılır', 'Faiz oranı kendiliğinden sıfıra iner', 'Tüketim sonsuza kadar artar'], 'Planlanan harcama üretimden azdır; satılamayan mallar stokta birikir. Firmalar bunun üzerine üretimi azaltır ve gelir, planlanan tasarruf planlanan yatırıma eşitlenene kadar düşer.'),
  ('Bir hanehalkının geliri 1.000 liradan 1.200 liraya çıktığında tüketimi 850 liradan 1.000 liraya yükselmiştir. Marjinal tüketim eğilimi kaçtır?', '0,75', ['0,85', '0,83', '1,25'], 'MTE = ΔC / ΔY = (1.000 − 850) / (1.200 − 1.000) = 150 / 200 = 0,75.'),
  ('Devlet aynı tutarı düşük gelirli ailelere ya da çok yüksek gelirli ailelere dağıtabilir. Kısa dönemde toplam tüketimi daha çok artıracak seçenek ve gerekçesi hangisidir?', 'Düşük gelirli ailelere vermek; marjinal tüketim eğilimleri daha yüksektir', ['Yüksek gelirli ailelere vermek; daha çok tasarruf ederler', 'İkisi aynı etkiyi yapar; tüketim yalnızca fiyatlara bağlıdır', 'Yüksek gelirli ailelere vermek; marjinal tüketim eğilimleri daha yüksektir'], 'Düşük gelirli haneler ek gelirin büyük bölümünü harcarken yüksek gelirli haneler önemli bir kısmını tasarruf eder.'),
  ('Tüketim fonksiyonu C = 100 + 0,8Y olan vergisiz bir ekonomide hanehalklarının toplam tasarrufu hangi gelir düzeyinde sıfır olur?', '500', ['100', '125', '800'], 'Tasarruf S = Y − C = −100 + 0,2Y\'dir. S = 0 için 0,2Y = 100, Y = 500 bulunur. Bu düzeyin altında negatif tasarruf yapılır.'),
  ('Tüketim fonksiyonu C = 80 + 0,6Y olan bir ekonomide tasarruf fonksiyonu hangisidir?', 'S = −80 + 0,4Y', ['S = 80 + 0,4Y', 'S = −80 + 0,6Y', 'S = 80 − 0,6Y'], 'S = Y − C = Y − 80 − 0,6Y = −80 + 0,4Y. Otonom tasarruf, otonom tüketimin eksi işaretlisidir.'),
  ('Bir ülkede hanehalklarının sahip olduğu konutların değeri hızla artarsa, kısa dönemde tüketim fonksiyonunun grafiğine ne olması beklenir?', 'Fonksiyon yukarı kayar', ['Fonksiyon boyunca aşağı hareket edilir', 'Fonksiyon aşağı kayar', 'Fonksiyonun eğimi sıfıra iner'], 'Servet artışı her gelir düzeyinde daha fazla tüketim yapılmasına yol açar; bu gelir dışı bir etken olduğundan eğri kayar. Gelir değişimi ise eğri boyunca hareket yaratır.'),
  ('Gelecekte işini kaybetme olasılığının arttığını düşünen hanehalklarının, gelirleri değişmediği hâlde daha fazla para biriktirmesine ne ad verilir?', 'İhtiyat amaçlı tasarruf', ['Zorunlu tasarruf', 'Negatif tasarruf', 'Otonom tüketim'], 'Belirsizlik arttığında insanlar olası gelir kayıplarına karşı tampon oluşturmak için tasarruflarını artırır.'),
  ('Modigliani\'nin yaşam döngüsü kuramına göre tipik bir bireyin servet birikimi yaşa göre nasıl bir seyir izler?', 'Çalışma yılları boyunca artar, emeklilik başında zirve yapar, sonra azalır', ['Doğumdan ölüme kadar sürekli azalır', 'Gençlikte en yüksek düzeye ulaşır, ardından ömür boyunca hiç durmadan sürekli düşer', 'Bütün yaşam boyunca sabit kalır'], 'Birey çalışırken birikim yapar, emekliliğe girerken servet en yüksek düzeydedir; emeklilikte bu birikimi harcayarak tüketimini sürdürür.'),
  ('Yatırım talebi eğrisinin faiz oranı ile yatırım miktarı arasında ters yönlü bir ilişki göstermesinin nedeni hangisidir?', 'Faiz yükseldikçe getirisi faizi aşan proje sayısı azalır', ['Faiz yükselince makine fiyatları düşer', 'Faiz yükselince firmaların kârı kendiliğinden artar', 'Faiz yükselince tasarruflar azalır, tüketim artar ve yatırım fonları tükenir'], 'Yüksek faiz hem borçlanma maliyetini hem de fonların fırsat maliyetini artırır; daha az proje bu eşiği aşabildiğinden yatırım düşer.'),
  ('Keynes\'in, yatırım kararlarının yalnız hesaplanmış getirilere değil, girişimcilerin kendiliğinden doğan iyimserlik ya da kötümserliğine de bağlı olduğunu anlatmak için kullandığı kavram hangisidir?', 'Hayvansal güdüler', ['Görünmez el', 'Yaratıcı yıkım', 'Rasyonel beklentiler'], 'Keynes \'Genel Teori\'de, belirsizlik altında yatırım kararlarının büyük ölçüde \'animal spirits\' denen içgüdüsel güvene dayandığını vurgulamıştır.'),
  ('Devletin ve dış ticaretin olmadığı bir ekonomide tüketim fonksiyonu C = 50 + 0,8Y ve planlanan yatırım 100 milyar liradır. Denge milli geliri kaç milyar liradır?', '750', ['150', '600', '1.250'], 'Dengede Y = C + I olur: Y = 50 + 0,8Y + 100. Buradan 0,2Y = 150 ve Y = 750 milyar lira bulunur.'),
  ('Kapalı bir ekonomide C = 100 + 0,75(Y − T), T = 80, I = 150 ve G = 120 milyar liradır. Denge milli geliri kaç milyar liradır?', '1.240', ['1.480', '1.000', '1.120'], 'Y = 100 + 0,75Y − 60 + 150 + 120 eşitliğinden 0,25Y = 310 ve Y = 1.240 milyar lira bulunur.'),
  ('Keynesyen çapraz diyagramında yatay eksende gelir, dikey eksende planlanan harcama bulunur. Bu diyagramda çizilen 45 derecelik doğrunun her noktası neyi gösterir?', 'Planlanan harcamanın gelire eşit olduğu durumları', ['Tüketimin sıfır olduğu gelir düzeylerini', 'Gerçekleşen yatırımın planlanan tasarruftan büyük olduğu noktaları', 'Gelirin tamamen vergiye gittiği noktaları'], '45 derece doğrusu üzerinde yatay ve dikey eksendeki değerler eşittir. Planlanan harcama doğrusunun bu doğruyu kestiği nokta denge gelirini verir.'),
  ('Basit Keynesyen modelde, kapalı ve vergisiz bir ekonomide planlanan toplam harcama doğrusunun eğimi neye eşittir?', 'Marjinal tüketim eğilimine', ['Ortalama tüketim eğiliminin gelire oranına', 'Faiz oranına', 'Çarpanın değerine'], 'Planlanan harcama C + I\'dir ve yatırım otonomdur. Gelir bir birim arttığında harcama yalnızca tüketim yoluyla MTE kadar artar.'),
  ('Basit Keynesyen gelir belirleme modelinin temel varsayımlarından biri hangisidir?', 'Kısa dönemde fiyatlar sabittir ve atıl kapasite vardır', ['Ekonomi her zaman tam istihdamdadır', 'Ücretler ve fiyatlar tam esnektir', 'Toplam arz, toplam talepten bağımsız olarak hep sabit kalır'], 'Model, üretimin talebe göre ayarlandığını varsayar. Bunun için fiyatların kısa dönemde değişmediği ve işsiz kaynakların bulunduğu kabul edilir.'),
  ('Marjinal tasarruf eğilimi yüksek olan bir ekonomide otonom harcama çarpanı, marjinal tasarruf eğilimi düşük olan bir ekonomiye göre nasıldır?', 'Daha küçüktür', ['Daha büyüktür', 'Her zaman 1\'e eşittir', 'Marjinal tasarruf eğiliminden bağımsızdır'], 'Basit çarpan 1 / MTasE\'dir. Her turda gelirin daha büyük kısmı tasarruf olarak akımdan çekildiği için harcama zinciri daha çabuk söner.'),
  ('İki ülkenin marjinal tüketim eğilimleri aynıdır, ancak A ülkesi gelirindeki artışın çok daha büyük bir kısmını ithal mallara harcamaktadır. Çarpan etkisi hangi ülkede daha zayıf olur ve neden?', 'A ülkesinde; ithalat yurt içi harcama zincirinden bir sızıntıdır', ['B ülkesinde; ithalat yurt içi geliri iki kat artırır', 'A ülkesinde; çünkü ithal mallar vergiden muaftır', 'İkisinde eşit; ithalatın çarpan üzerinde hiçbir etkisi bulunmaz, yalnız tüketim önemlidir'], 'İthal mallara yapılan harcama yabancı üreticilerin gelirine dönüşür. Yurt içi gelir zinciri her turda daha çok zayıfladığından çarpan küçülür.'),
  ('Tam istihdam gelirinin 1.000 milyar lira olduğu bir ekonomide denge geliri 1.200 milyar liradır ve çarpan 4\'tür. Enflasyonist açığı kapatmak için toplam harcamanın ne kadar azalması gerekir?', '50 milyar lira', ['200 milyar lira', '800 milyar lira', '300 milyar lira'], 'Gelir farkı 200 milyar liradır. Çarpan 4 olduğundan harcamada 200 / 4 = 50 milyar liralık bir azalma gelirde 200\'lük düşüş sağlar; bu tutar enflasyonist açıktır.'),
  ('Basit Keynesyen modelde marjinal tüketim eğilimi 0,9\'dan 0,75\'e düşerse otonom harcama çarpanı nasıl değişir?', '10\'dan 4\'e düşer', ['4\'ten 10\'a çıkar', '9\'dan 7,5\'e düşer', 'Değişmez, 1 olarak kalır'], 'Çarpan 1 / (1 − MTE)\'dir: 1 / 0,1 = 10 ve 1 / 0,25 = 4. Tüketim eğilimi azalınca çarpan küçülür.'),
  ('Fiyat düzeyi düştüğünde insanların işlem yapmak için daha az paraya ihtiyaç duyması, borçlanma maliyetinin gerilemesi ve yatırımların artması toplam talep eğrisinin negatif eğimini açıklayan hangi etkidir?', 'Faiz oranı etkisi', ['Servet etkisi', 'Dış ticaret etkisi', 'Mandal etkisi'], 'Keynes etkisi de denen faiz oranı etkisinde düşük fiyat düzeyi para talebini azaltır; faiz düşer, faize duyarlı harcamalar artar.'),
  ('Bir ülkede fiyat düzeyi diğer ülkelere göre düştüğünde yerli malların görece ucuzlayıp yabancıların bu mallara yönelmesi, toplam talep eğrisinin eğimine hangi etki olarak katkı yapar?', 'Dış ticaret (döviz kuru) etkisi', ['Faiz oranı etkisi', 'Reel kasa (Pigou) etkisi ve servet', 'Hızlandıran etkisi'], 'Yurt içi fiyatların düşmesi ihracatı artırıp ithalatı azaltır; böylece daha düşük fiyat düzeyinde daha fazla mal talep edilir.'),
  ('Toplam talep-toplam arz modelinde aşağıdakilerden hangisi toplam talep eğrisini kaydırmaz, yalnızca eğri üzerinde bir harekete yol açar?', 'Genel fiyat düzeyinin değişmesi', ['Tüketici güveninin artması', 'Ticaret ortaklarında resesyon yaşanması', 'Firmaların gelecek beklentilerinin kötüleşmesi'], 'Eğrinin eksenlerinden biri fiyat düzeyi olduğu için fiyat değişimi eğri boyunca harekettir. Diğer etkenler her fiyat düzeyinde harcamayı değiştirerek eğriyi kaydırır.'),
  ('Uzun dönem toplam arz eğrisinin dikey çizilmesinin nedeni nedir?', 'Uzun dönemde üretim fiyat düzeyine değil, emek, sermaye ve teknolojiye bağlıdır', ['Uzun dönemde fiyatlar hiç değişmediği ve bütün sözleşmeler sabit kaldığı için böyle çizilir', 'Uzun dönemde talep sonsuz esnek olduğu için', 'Uzun dönemde işsizlik hep sıfır olduğu için'], 'Uzun dönemde ücretler ve fiyatlar tam uyum sağlar. Bu nedenle ekonominin üretimi, fiyat düzeyinden bağımsız olarak potansiyel üretim düzeyinde belirlenir.'),
  ('Aşağıdakilerden hangisi uzun dönem toplam arz eğrisini sağa kaydırır?', 'Üretimde verimliliği artıran yeni bir teknolojinin yaygınlaşması', ['Genel fiyat düzeyinin yüzde 10 artması', 'Hanehalklarının her gelir düzeyinde tüketim harcamalarını artırması', 'Para arzının bir defalık artırılması'], 'Uzun dönem arz, kaynaklar ve teknolojiyle belirlenir. Teknolojik ilerleme potansiyel üretimi artırır. Talep yönlü değişiklikler ise uzun dönemde yalnızca fiyatları etkiler.'),
  ('Sendikalarla yapılan toplu sözleşmeler sonucunda ekonomi genelinde nominal ücretlerin verimlilikten bağımsız olarak hızla artması kısa dönem toplam arz eğrisini nasıl etkiler?', 'Sola (yukarı) kaydırır', ['Sağa (aşağı) kaydırır', 'Dikey hâle getirir', 'Etkilemez; yalnızca toplam talep değişir'], 'Ücretler firmalar için bir maliyettir. Maliyet artışı her fiyat düzeyinde daha az üretim yapılmasına yol açar ve arz eğrisini sola kaydırır.'),
  ('Keynesyen toplam arz eğrisinin derin bir durgunluğa karşılık gelen yatay kesiminde toplam talep artarsa ne olur?', 'Fiyat düzeyi neredeyse değişmeden üretim artar', ['Üretim değişmeden yalnızca fiyatlar artar ve enflasyon hızlanır', 'Hem fiyat düzeyi hem üretim düşer', 'Ekonomi derhâl hiperenflasyona girer'], 'Bu kesimde çok sayıda atıl makine ve işsiz işçi vardır; firmalar maliyetleri artmadan üretimi genişletebildiğinden talep artışı fiyatlara pek yansımaz.'),
  ('Potansiyel düzeyinde çalışan bir ekonomide toplam talep kalıcı olarak artırılırsa uzun dönemde sonuç ne olur?', 'Üretim potansiyele döner, yalnızca fiyat düzeyi daha yüksek kalır', ['Üretim kalıcı olarak potansiyelin üzerinde kalır', 'Fiyat düzeyi eski düzeyine döner, üretim kalıcı artar', 'Hem üretim hem fiyatlar başlangıçtaki düzeylerine döner ve hiçbir kalıcı değişiklik olmaz'], 'Kısa dönemde üretim artar, ancak ücretler ve beklentiler zamanla uyum sağlayınca kısa dönem arz sola kayar. Uzun dönemde dikey arz eğrisi nedeniyle yalnızca fiyatlar yükselmiş olur.'),
  ('Üretimin potansiyelin altında kaldığı bir durgunlukta hiçbir politika uygulanmazsa klasik görüşe göre ekonomi kendiliğinden nasıl uyum sağlar?', 'İşsizlik ücretleri zamanla düşürür, kısa dönem arz sağa kayar', ['Toplam talep kendiliğinden sola kayar', 'Potansiyel üretim kalıcı olarak düşer ve uyum süreci kendiliğinden sona erer', 'Fiyat düzeyi sürekli yükselerek üretimi artırır'], 'İşsizlik baskısıyla nominal ücretler ve maliyetler geriler. Kısa dönem arz eğrisi sağa kaydıkça fiyatlar düşer ve üretim potansiyele döner; bu süreç uzun sürebilir.'),
  ('Gerçekleşen üretimin potansiyel üretimin üzerinde olduğu pozitif üretim açığı döneminde hangisinin görülmesi beklenir?', 'İşsizliğin doğal oranın altına inmesi ve enflasyon baskısının artması', ['İşsizliğin doğal oranın üzerine çıkması ve fiyatların düşmesi', 'Fabrikalarda kapasite kullanımının olağan düzeyin altına inmesi', 'Ücretler üzerinde aşağı yönlü baskının giderek artması ve stokların birikmesi'], 'Ekonomi kapasitesinin üzerinde çalışırken işgücü piyasası sıkışır; ücretler ve fiyatlar yükselme eğilimine girer.'),
  ('Toplam talep-toplam arz modelinde, ekonominin aynı anda hem üretim düşüşü hem de fiyat artışı yaşamasına en çok hangi gelişme yol açar?', 'Kısa dönem toplam arzın sola kayması', ['Toplam talebin sağa kayması', 'Toplam talebin sola kayması', 'Uzun dönem toplam arz eğrisinin sağa kayması'], 'Talep şokları üretim ve fiyatları aynı yönde hareket ettirir. Üretimin düşüp fiyatların arttığı ters yönlü hareket ancak olumsuz bir arz şokuyla açıklanır.'),
  ('Bir ülkede kriz sonrasında üretimin düşüp yıllarca kriz öncesi büyüme eğilimine geri dönememesi hangi toparlanma biçimine uyar?', 'L tipi', ['V tipi', 'W tipi', 'Ters U tipi'], 'L harfi, sert düşüşün ardından uzun ve yatay bir durgunluğu simgeler; ekonomi eski patikasına dönemez.'),
  ('Yaklaşık 45-60 yıl süren ve büyük teknolojik devrimlerle ilişkilendirilen \'uzun dalgalar\' hangi Rus iktisatçının adıyla anılır?', 'Nikolay Kondratiev', ['Wassily Leontief', 'Simon Kuznets', 'Ivan Pavlov'], 'Kondratiev 1920\'lerde kapitalist ekonomilerde yarım yüzyıl dolayında süren uzun dalgaların varlığını ileri sürmüştür.'),
  ('Ekonomik dalgalanmaların temel kaynağının teknoloji ve verimlilik şokları olduğunu, dalgalanmaların piyasaların bu şoklara verdiği etkin tepki olduğunu savunan yaklaşım hangisidir?', 'Reel konjonktür kuramı', ['Keynesyen talep kuramı', 'Politik konjonktür kuramı', 'Eksik tüketim kuramı'], 'Kydland ve Prescott\'un 1982 tarihli çalışmasıyla gelişen kurama göre durgunluklar talep yetersizliğinden değil, verimlilik düşüşlerinden kaynaklanır.'),
  ('William Nordhaus\'un 1975\'te geliştirdiği politik konjonktür modeline göre iktidardaki hükümetler hangi davranışı sergileme eğilimindedir?', 'Seçim öncesi ekonomiyi canlandırıp sonrasında sıkılaştırma', ['Seçimlerden bağımsız olarak hep aynı politikayı uygulama', 'Seçim öncesi işsizliği bilerek artırma', 'Seçimden hemen sonra harcamaları rekor düzeye çıkarma'], 'Modele göre hükümetler seçmenlerin kısa hafızasından yararlanıp seçimden önce işsizliği düşürür; enflasyonun bedeli seçim sonrasına kalır.'),
  ('Ekonomi toparlanmaya başladıktan sonra bile işsizlik oranının bir süre daha yükselmeyi sürdürmesi, işsizliğin hangi tür gösterge olarak sınıflandırılmasının nedenidir?', 'Gecikmeli gösterge', ['Öncü gösterge', 'Eşzamanlı gösterge', 'Mevsimsel gösterge'], 'Firmalar toparlanmanın kalıcı olduğuna ikna olana kadar işe alımı erteler. Bu nedenle işsizlik ekonomik faaliyeti geriden izler.'),
  ('Ekonomik dalgalanmalarda hanehalklarının otomobil ve beyaz eşya gibi dayanıklı mallara yaptığı harcamalar, gıda gibi dayanıksız mallara göre nasıl davranır?', 'Çok daha sert dalgalanır', ['Hiç dalgalanmaz', 'Konjonktürle ters yönde hareket eder', 'Gıda harcamalarıyla tam olarak aynı oranda değişir'], 'Dayanıklı malların alımı kolayca ertelenebilir; belirsizlik dönemlerinde haneler önce bu harcamaları keser, canlanmada ise yoğun biçimde yeniler.'),
  ('TÜİK\'in Hanehalkı İşgücü Araştırması\'nda \'çalışma çağındaki nüfus\' hangi grubu kapsar?', '15 ve daha yukarı yaştaki kurumsal olmayan nüfusu', ['18-65 yaş arasındaki bütün vatandaşları', 'Yalnızca sigortalı olarak çalışanları', 'Ülkede yaşayan bütün nüfusu, çocuklar ve yaşlılar da dâhil olmak üzere'], 'TÜİK, okul, yurt, cezaevi ve kışla gibi kurumlarda yaşayanlar dışındaki 15 ve üzeri yaştaki nüfusu çalışma çağındaki nüfus olarak alır.'),
  ('Uluslararası Çalışma Örgütü (ILO) standartlarına göre bir kişinin \'istihdamda\' sayılması için referans haftasında en az ne kadar çalışmış olması yeterlidir?', 'Bir saat', ['Yirmi saat', 'Kırk saat', 'Bir tam iş günü olan sekiz saat'], 'ILO tanımına göre referans haftasında kâr, ücret ya da yevmiye karşılığında en az bir saat çalışan kişi istihdamda sayılır; bu tanım çok kısa süreli çalışmaları da kapsar.'),
  ('TÜİK tanımına göre istihdamda olmayan bir kişinin \'işsiz\' sayılabilmesi için hangi iki koşulu birlikte sağlaması gerekir?', 'Son dört haftada iş aramış olması ve iki hafta içinde işbaşı yapabilecek durumda olması', ['İŞKUR\'a kayıtlı olması ve işsizlik ödeneği alması', 'Daha önce en az bir yıl çalışmış olması ve sigortalı bulunması', 'Üniversite mezunu olması ve en az altı aydır işsiz kalmış olması'], 'İşsiz tanımı aktif iş arama ve işe hazır olma ölçütlerine dayanır. İŞKUR\'a kayıt ya da ödenek almak gerekmez.'),
  ('Ailesine ait bir dükkânda ücret almadan düzenli olarak çalışan bir genç işgücü istatistiklerinde nasıl sınıflanır?', 'Ücretsiz aile işçisi olarak istihdamda sayılır', ['Ücret almadığı için işsiz sayılır', 'İşgücü dışında, ev işleriyle meşgul olarak sayılır', 'Eksik istihdam kapsamında, kayıtlı işsiz olarak gösterilir'], 'ILO ve TÜİK tanımlarında aile işletmesinde ücretsiz çalışanlar da üretime katıldıkları için istihdamdadır; işteki durumları \'ücretsiz aile işçisi\' olarak gösterilir.'),
  ('Bir ülkede işsiz sayısı bir yılda değişmeyip 4 milyonda kalırken işgücü 40 milyondan 42 milyona çıkmıştır. İşsizlik oranı için hangisi doğrudur?', 'Yaklaşık yüzde 9,5\'e gerilemiştir', ['Yüzde 10\'da sabit kalmıştır', 'Yüzde 10,5\'e yükselmiştir', 'Yüzde 8\'e düşmüş ve istihdam 4 milyon artmıştır'], 'Oran 4 / 40 = yüzde 10\'dan 4 / 42 ≈ yüzde 9,5\'e iner. İşgücüne yeni katılanların tamamı iş bulduğu için işsiz sayısı sabitken oran düşmüştür.'),
  ('Bir ekonomide işsizlik oranı düşerken istihdam oranı da düşüyorsa bunun en olası açıklaması hangisidir?', 'Birçok kişi iş aramayı bırakıp işgücünden çıkmıştır', ['Çok sayıda yeni iş yaratılmış ve herkes işe girmiştir', 'Çalışma çağındaki nüfus hızla azalmıştır', 'İstatistik kurumu işsizliği ölçmeyi bırakmış ve tahmin yapmaya başlamıştır'], 'İşgücünden çıkanlar işsiz sayılmadığından işsizlik oranı düşer; ama çalışanların nüfusa oranı da düşer. Bu, işgücü piyasasının aslında zayıfladığını gösterir.'),
  ('İşgücüne katılma oranı yüzde 60 olan bir ülkede çalışma çağındaki nüfus 70 milyon, işsizlik oranı yüzde 10\'dur. İstihdamdaki kişi sayısı kaç milyondur?', '37,8', ['42', '63', '4,2'], 'İşgücü 70 × 0,60 = 42 milyondur. İşsizler 42 × 0,10 = 4,2 milyon olduğundan istihdam 42 − 4,2 = 37,8 milyondur.'),
  ('Hemen her ülkede genç işsizlik oranının genel işsizlik oranından yüksek çıkmasının en önemli nedenlerinden biri hangisidir?', 'Deneyimsizlik ve işe girişte uzayan arama süreleri', ['Gençlerin işgücü istatistiklerine hiç dâhil edilmemesi', 'Gençlere asgari ücretin hiçbir ülkede uygulanmaması', 'Gençlerin daha yüksek emekli aylığı alması ve çalışmaya ihtiyaç duymaması'], 'Okuldan yeni çıkan gençler deneyim ve bağlantı eksikliği yaşar, sık iş değiştirir; ekonomik durgunluklarda ilk işten çıkarılanlar da çoğu zaman en kıdemsizlerdir.'),
  ('İş aramadığı hâlde bir iş teklifi gelse hemen çalışmaya başlayabilecek kişiler TÜİK\'in tamamlayıcı göstergelerinde hangi grupta yer alır?', 'Potansiyel işgücü', ['İstihdam', 'İşsizler', 'Mevsimlik işçiler ve tarım işçileri grubu'], 'Bu kişiler aktif iş arama koşulunu sağlamadıkları için işsiz sayılmaz. Ancak çalışmaya hazır oldukları için potansiyel işgücüne dâhil edilir.'),
  ('Keynes\'in \'gönülsüz işsizlik\' kavramı hangi durumu anlatır?', 'Geçerli ücretle çalışmaya hazır olduğu hâlde iş bulamamak', ['Daha yüksek ücret beklentisiyle iş tekliflerini reddetmek', 'Emekli olduğu için iş aramamak', 'Mevsim koşulları nedeniyle birkaç ay çalışmamak ve sonra işe dönmek'], 'Keynes\'e göre toplam talep yetersizse insanlar mevcut ya da daha düşük ücrete razı olsalar bile iş bulamaz; bu gönülsüz işsizliktir.'),
  ('Bir ülkenin yapısal işsizliğini azaltmak için en uygun önlem aşağıdakilerden hangisidir?', 'Mesleki eğitimle işsizlere aranan becerileri kazandırmak', ['Faiz oranlarını kısa süreliğine düşürmek', 'Yaz aylarında geçici işler yaratmak', 'Tüketicilere bir defalık nakit ödeme yapmak ve harcamayı artırmak'], 'Yapısal işsizlik becerilerle boş işlerin uyumsuzluğundan doğar. Talebi artırmak bu uyumsuzluğu gidermez; yeniden beceri kazandırma ise doğrudan soruna yöneliktir.'),
  ('İşsizlik ödeneğinin süresinin uzatılmasının arama kuramına göre olası bir yan etkisi hangisidir?', 'İşsizlerin daha uzun süre arayarak friksiyonel işsizliği artırması', ['Tüm işsizlerin ertesi gün işe başlaması', 'Yapısal işsizliğin tamamen ortadan kalkması', 'İşverenlerin ücretleri hemen yarıya indirmesi ve işe alımı artırması'], 'Ödenek, aramanın maliyetini düşürür ve rezervasyon ücretini yükseltir. Daha iyi eşleşme sağlasa da işsizlik süresini uzatabilir.'),
  ('Makroekonomide NAIRU kısaltmasıyla anılan büyüklük hangisidir?', 'Enflasyonu hızlandırmayan işsizlik oranı', ['Ulusal ortalama ücret endeksi', 'Reel faizin sıfır olduğu işsizlik düzeyi', 'İşgücüne katılma oranının en yüksek olduğu yaş grubu'], 'NAIRU (Non-Accelerating Inflation Rate of Unemployment), işsizliğin altına inildiğinde enflasyonun hızlanmaya başladığı orandır ve doğal oranla yakından ilişkilidir.'),
  ('Makroekonomide \'tam istihdam\' denildiğinde neden işsizliğin sıfır olduğu bir durum kastedilmez?', 'İş değiştirme ve arama nedeniyle bir miktar işsizlik her zaman bulunur', ['Yasalar işsizliğin sıfıra inmesini yasakladığı için', 'Tam istihdamda bütün çalışanlar emekli olduğu için', 'İşsizlik oranı ancak negatif değerler alabildiği için hesaplanamaz'], 'Friksiyonel ve yapısal işsizlik sağlıklı bir ekonomide de vardır. Tam istihdam, işsizliğin bu doğal düzeye inmesi demektir.'),
  ('Aşağıdakilerden hangisi ücretlerin denge düzeyine inmesini engelleyerek işsizliğe yol açabilen \'ücret katılığı\' nedenlerinden biri değildir?', 'İşçilerin daha fazla saat çalışmak istemesi', ['Asgari ücret yasaları', 'Sendikaların toplu pazarlık gücü', 'Firmaların etkin ücret ödemesi'], 'Asgari ücret, sendika gücü ve etkin ücret ücretleri denge üzerinde tutabilir. Çalışma isteğinin artması ise emek arzını artırır ve ücretler üzerinde aşağı yönlü baskı yaratır.'),
  ('Uzun süreli işsizliğin bireyler ve toplum üzerindeki maliyetleri arasında aşağıdakilerden hangisi yer almaz?', 'Kişinin vergi yükünün artması', ['Ruh ve beden sağlığının bozulması', 'Becerilerin ve özgüvenin yitirilmesi', 'Hanenin gelirinin ve birikiminin erimesi'], 'Araştırmalar uzun süreli işsizliğin sağlık sorunları, beceri kaybı ve yoksullukla bağlantılı olduğunu gösterir. İşsiz kişinin geliri düştüğü için vergi yükü artmaz, azalır.'),
  ('Phillips eğrisine adını veren A. W. (Bill) Phillips hangi ülkede doğmuştur?', 'Yeni Zelanda', ['Avustralya', 'Kanada', 'İskoçya'], 'Alban William Phillips Yeni Zelandalıdır; çalışmalarını London School of Economics\'te yürütmüş, ayrıca ekonomiyi su akışıyla gösteren MONIAC makinesini yapmıştır.'),
  ('Friedman ve Phelps\'in yaklaşımına göre uzun dönem Phillips eğrisi hangi işsizlik oranında dikey olarak yer alır?', 'Doğal işsizlik oranında', ['Sıfır işsizlik oranında', 'Yüzde 50 işsizlik oranında', 'Genç işsizlik oranında'], 'Uzun dönemde beklentiler gerçekleşen enflasyona uyum sağlar ve işsizlik, enflasyon ne olursa olsun doğal oranına döner. Bu yüzden eğri doğal oranda dikeydir.'),
  ('Beklentilerle genişletilmiş Phillips eğrisi π = πᵉ − 0,5(u − uₙ) biçimindedir. Beklenen enflasyon yüzde 5, doğal işsizlik oranı yüzde 6 ve gerçekleşen işsizlik yüzde 4 ise enflasyon yüzde kaç olur?', '6', ['4', '5', '7'], 'π = 5 − 0,5 × (4 − 6) = 5 + 1 = 6. İşsizlik doğal oranın altında olduğu için enflasyon beklenenin üzerine çıkar.'),
  ('Hanehalkı ve firmaların beklediği enflasyon oranı yükselirse kısa dönem Phillips eğrisi nasıl etkilenir?', 'Yukarı kayar', ['Aşağı kayar', 'Yatay hâle gelir', 'Uzun dönem eğrisiyle birlikte sola kayar'], 'Beklenen enflasyon arttığında her işsizlik düzeyinde gerçekleşen enflasyon daha yüksek olur; ödünleşim daha kötü bir konuma taşınır.'),
  ('Bir ham madde fiyat şoku nedeniyle maliyetlerin artması kısa dönem Phillips eğrisini nasıl etkiler?', 'Eğriyi yukarı kaydırır; aynı işsizlikte enflasyon artar', ['Eğriyi aşağı kaydırır; aynı işsizlikte enflasyon düşer', 'Uzun dönem eğrisini sağa doğru yatırır', 'Eğri üzerinde aşağı doğru bir hareket yaratır ve işsizliği azaltır'], 'Olumsuz arz şokları, toplam arz modelindeki sola kaymanın Phillips eğrisindeki karşılığıdır: her işsizlik düzeyinde enflasyon daha yüksektir.'),
  ('Okun yasasının değişim biçimi Δu = −0,5 × (g − 3) olarak tahmin edilmiştir (g: yüzde olarak reel büyüme). Bir yıl ekonomi yalnızca yüzde 1 büyürse işsizlik oranı nasıl değişir?', '1 puan artar', ['1 puan azalır', '2 puan artar', 'Değişmez, çünkü ekonomi büyümüştür'], 'Δu = −0,5 × (1 − 3) = +1. Büyüme potansiyelin (yüzde 3) altında kaldığı için ekonomi büyüse bile işsizlik artar.'),
  ('Bir ekonomi bir çeyrekte önceki çeyreğe göre yüzde 1 büyümüştür. Bu hız bir yıl boyunca sürseydi yıllık büyüme yaklaşık yüzde kaç olurdu (yıllıklandırılmış büyüme)?', '4,06', ['4', '1', '12,68'], 'Yıllıklandırma bileşik olarak yapılır: (1,01)⁴ − 1 ≈ 0,0406, yani yaklaşık yüzde 4,06.'),
  ('Bir ekonomi bir yıl yüzde 10 küçülüp ertesi yıl yüzde 10 büyürse iki yılın sonunda GSYH başlangıç düzeyine göre nerededir?', 'Yüzde 1 daha düşüktür', ['Başlangıç düzeyine tam olarak eşittir', 'Yüzde 1 daha yüksektir', 'Yüzde 10 daha düşüktür'], '100 birimlik GSYH önce 90\'a iner, sonra 90 × 1,1 = 99 olur. Küçük bir tabandan hesaplanan büyüme, kaybı tam telafi etmez.'),
  ('TÜİK\'in açıkladığı \'yıllık büyüme\' ile \'çeyreklik büyüme\' arasındaki fark hangisidir?', 'Yıllık büyüme bir önceki yılın aynı çeyreğine, çeyreklik büyüme bir önceki çeyreğe göre hesaplanır', ['Yıllık büyüme nominal, çeyreklik büyüme her zaman reel olarak hesaplanır', 'Çeyreklik büyüme yalnızca tarım sektörünü kapsar, sanayi ve hizmet sektörlerini ise hiç içermez', 'İkisi aynı veriyi farklı para birimiyle gösterir'], 'Yıllık karşılaştırma mevsimsellikten büyük ölçüde etkilenmez; çeyreklik karşılaştırma ise mevsim etkisinden arındırılmış seriyle yapılır ve dönüm noktalarını daha erken gösterir.'),
  ('GSYH içinde payı yüzde 60 olan hanehalkı tüketimi bir yılda reel olarak yüzde 5 artmıştır. Tüketimin o yılki büyümeye katkısı kaç puandır?', '3', ['5', '60', '0,3'], 'Bir bileşenin büyümeye katkısı, önceki dönem payı ile kendi büyüme oranının çarpımıdır: 0,60 × 5 = 3 puan.'),
  ('Bir ülkenin büyümesinin büyük ölçüde daha fazla işçi ve makine kullanılmasından, çok az ölçüde verimlilik artışından kaynaklanmasına ne ad verilir?', 'Yaygın (ekstansif) büyüme', ['Yoğun (intensif) büyüme', 'İçsel büyüme ve yaratıcı yıkım', 'Dengeli büyüme'], 'Yaygın büyüme faktör birikimine dayanır ve azalan getiriler nedeniyle zamanla yavaşlar. Yoğun büyüme ise verimlilik artışıyla sağlanır.'),
  ('Bir toplam üretim fonksiyonu Y = A·K^0,3·L^0,7 biçimindedir. Sermaye ve emek aynı anda iki katına çıkarılırsa üretime ne olur?', 'İki katına çıkar', ['Dört katına çıkar', 'Yüzde 30 artar', 'Yüzde 70 artar'], 'Üslerin toplamı 0,3 + 0,7 = 1 olduğundan fonksiyon ölçeğe göre sabit getirilidir: bütün girdiler iki katına çıkınca üretim de iki katına çıkar.'),
  ('Ülkeler arasında emek verimliliği karşılaştırılırken çalışan başına üretim yerine çalışma saati başına üretimin tercih edilmesinin nedeni nedir?', 'Ülkelerde yıllık ortalama çalışma süreleri çok farklı olabildiği için', ['Çalışan sayısı hiçbir ülkede ölçülmediği için', 'Saat başına verim her zaman daha yüksek çıktığı için', 'Çalışma saatleri bütün ülkelerde uluslararası anlaşmalarla eşitlendiği için'], 'Bir ülkede çalışanlar yılda çok daha uzun saat çalışıyorsa çalışan başına üretim yüksek görünür; saat başına ölçüm bu farkı ortadan kaldırır.'),
  ('Solow büyüme modelinde \'durağan durum\' hangi koşulun sağlandığı uzun dönem dengesidir?', 'İşçi başına yatırımın, işçi başına sermayeyi sabit tutmaya yetecek düzeye eşit olması', ['Tasarrufların sıfır olması', 'Bütün gelirin tüketilip hiç amortisman yapılmaması', 'Nüfusun ve sermaye stokunun her yıl aynı oranda azalmaya devam etmesi ve sıfıra yaklaşması'], 'Durağan durumda yeni yatırım yalnızca aşınan sermayeyi ve yeni katılan işçilerin sermaye ihtiyacını karşılar; işçi başına sermaye ve üretim değişmez.'),
  ('Solow modelinde işçi başına üretim y = √k, tasarruf oranı 0,2 ve amortisman oranı 0,1\'dir (nüfus artışı ve teknoloji yok). Durağan durumda işçi başına sermaye (k) kaçtır?', '4', ['2', '0,5', '20'], 'Durağan durumda s·√k = δ·k olur. Buradan √k = s / δ = 0,2 / 0,1 = 2 ve k = 4 bulunur; işçi başına üretim 2\'dir.'),
  ('Solow modeline göre diğer her şey aynıyken nüfus artış hızı daha yüksek olan bir ülkenin durağan durumdaki işçi başına geliri nasıldır?', 'Daha düşüktür', ['Daha yüksektir', 'Nüfus artışından etkilenmez', 'Sonsuza kadar artar ve hiç durağan duruma ulaşmaz'], 'Hızlı nüfus artışında yatırımın daha büyük kısmı yeni işçilere sermaye sağlamaya gider; bu nedenle işçi başına sermaye ve gelir daha düşük düzeyde dengelenir.'),
  ('Teknolojik değişmeyi modelin dışında verili kabul etmek yerine Ar-Ge ve fikir üretimiyle model içinde açıklayan çalışmaları nedeniyle 2018 Nobel İktisat Ödülü\'nü alan iktisatçı kimdir?', 'Paul Romer', ['Robert Lucas', 'Robert Barro', 'Angus Deaton'], 'Romer, ödülü iklim ekonomisi üzerine çalışan William Nordhaus ile paylaşmıştır. Onun içsel büyüme kuramı fikirlerin birikimini büyümenin motoru olarak görür.'),
  ('İçsel büyüme kuramcılarına göre serbest piyasada Ar-Ge yatırımlarının toplum için en uygun düzeyin altında kalmasının nedeni hangisidir?', 'Ar-Ge\'nin bir kısmı başkalarına yayıldığı için sosyal getirisinin özel getiriden yüksek olması', ['Ar-Ge\'nin hiçbir getiri sağlamaması', 'Ar-Ge\'nin yalnızca devlet tarafından yapılmasının yasal bir zorunluluk olması ve firmalara yasaklanması', 'Firmaların Ar-Ge harcamalarının her zaman vergiden düşülememesi'], 'Yeni bilgi rakip firmalara ve başka sektörlere sızar. Yatırımı yapan firma bu faydanın tamamını elde edemediği için toplumsal açıdan gerekenden az Ar-Ge yapar.'),
  ('Daron Acemoğlu ve James Robinson\'ın \'Ulusların Düşüşü\' adlı kitabında ülkeler arasındaki zenginlik farkını açıklamak için yaptığı temel ayrım hangisidir?', 'Kapsayıcı ve sömürücü kurumlar', ['Tarım ve sanayi toplumları', 'Sıcak ve soğuk iklimler', 'Denize kıyısı olan ve olmayan ülkeler'], 'Yazarlara göre mülkiyet haklarını güvenceye alan ve geniş kesimlere fırsat tanıyan kapsayıcı kurumlar büyümeyi destekler; dar bir elitin çıkarına işleyen sömürücü kurumlar ise engeller.'),
  ('Daron Acemoğlu, Simon Johnson ve James Robinson\'ın 2024\'te Nobel İktisat Ödülü\'nü almasını sağlayan çalışmalarının ana konusu nedir?', 'Kurumların nasıl oluştuğu ve ülkelerin refahını nasıl etkilediği', ['Para politikasında enflasyon hedeflemesi', 'Oyun kuramında açık artırma tasarımı', 'Tüketicinin belirsizlik altındaki seçim davranışı ve sınırlı rasyonellik'], 'Ödül, sömürgecilik döneminde kurulan kurumların bugünkü gelir farklarını nasıl açıkladığını gösteren çalışmalara verilmiştir.'),
  ('Coğrafyası, kültürü ve tarihi büyük ölçüde ortak olan Kuzey ve Güney Kore arasındaki çok büyük gelir farkı, büyüme literatüründe hangi açıklamanın lehine kanıt olarak gösterilir?', 'Kurumların belirleyici olduğu görüşünün', ['İklimin belirleyici olduğu görüşünün', 'Doğal kaynakların belirleyici olduğu görüşünün', 'Nüfus yoğunluğunun belirleyici olduğu görüşünün ve iklimin'], 'İki ülke 1945\'te bölünmeden önce benzer koşullara sahipti. Ayrışmanın ardından ekonomik ve siyasal kurumların farklılaşması gelir farkının en güçlü açıklaması kabul edilir.'),
  ('Jeffrey Sachs gibi iktisatçıların vurguladığı \'coğrafya hipotezine\' göre denize kıyısı olmayan ve tropikal hastalıkların yaygın olduğu ülkelerin büyümesini zorlaştıran etkenler hangileridir?', 'Yüksek taşıma maliyetleri ve hastalık yükü', ['Aşırı sanayileşme ve kirlilik', 'Yüksek tasarruf oranı ve hızla azalan nüfus', 'Güçlü mülkiyet hakları ve yaygın eğitim'], 'Coğrafya hipotezi, dünya ticaretine erişimin pahalı olması ile sıtma gibi hastalıkların verimliliği ve beşeri sermayeyi düşürmesini büyüme önünde temel engel olarak görür.'),
  ('Mutlak yoksulluk ile göreli yoksulluk arasındaki temel fark hangisidir?', 'Mutlak yoksulluk temel ihtiyaçlara, göreli yoksulluk toplumun genel gelir düzeyine göre tanımlanır', ['Mutlak yoksulluk yalnızca kentlerde, göreli yoksulluk yalnızca kırsalda ölçülür', 'İkisi de aynı sınırı kullanır, yalnızca adları farklıdır', 'Göreli yoksulluk sadece gelişmekte olan ülkelerde hesaplanır ve gelişmiş ülkelerde hiçbir şekilde kullanılmaz'], 'Mutlak yoksulluk sınırı, beslenme ve barınma gibi asgari ihtiyaçların maliyetine dayanır. Göreli yoksulluk ise kişinin toplumdaki ortanca gelirin belli bir oranının altında kalmasıdır.'),
  ('TÜİK\'in gelir ve yaşam koşulları araştırmasında göreli yoksulluk sınırı genellikle neye göre belirlenir?', 'Eşdeğer hanehalkı kullanılabilir medyan gelirinin belirli bir yüzdesine', ['Asgari ücretin iki katına', 'Kişi başı GSYH\'nin dörtte birine', 'Ortalama kira bedelinin üç katına ve hanenin aylık gıda harcamasının toplamına'], 'TÜİK, eşdeğer medyan gelirin yüzde 50\'si ve yüzde 60\'ı gibi sınırları kullanarak göreli yoksulluk oranlarını hesaplar.'),
  ('Yoksul hanelerin gelirlerinin yoksulluk sınırına ne kadar uzak olduğunu, yani yoksulluğun derinliğini ölçen göstergeye ne ad verilir?', 'Yoksulluk açığı', ['Yoksulluk oranı', 'Bağımlılık oranı', 'Gini katsayısı'], 'Yoksulluk oranı yalnızca sınırın altındakilerin payını verir. Yoksulluk açığı ise bu kişilerin sınıra ortalama uzaklığını ölçer.'),
  ('BM Kalkınma Programı ile Oxford Üniversitesi\'nin 2010\'da geliştirdiği Çok Boyutlu Yoksulluk Endeksi\'nin gelire dayalı ölçütlerden farkı nedir?', 'Sağlık, eğitim ve yaşam koşullarındaki yoksunlukları birlikte ölçer', ['Yalnızca kişi başı geliri ölçer', 'Yalnızca gelişmiş ülkelerde uygulanır', 'Yoksulluğu yalnızca döviz kuruna ve ithal malların fiyatlarına göre hesaplar'], 'Endeks, beslenme, okula devam, temiz su, elektrik ve barınma gibi göstergelerdeki eş zamanlı yoksunlukları ölçerek yoksulluğun çok boyutlu yapısını gösterir.'),
  ('Bebek ölüm oranının bir ülkenin kalkınma düzeyinin güçlü bir göstergesi sayılmasının nedeni nedir?', 'Sağlık hizmeti, beslenme, temiz su ve eğitim düzeyini birlikte yansıtması', ['Doğrudan kişi başı ihracatı ölçmesi', 'Yalnızca iklim koşullarına bağlı olması', 'Her ülkede aynı değeri alması ve bu nedenle çok kolay hesaplanabilmesi'], 'Bebek ölümleri birçok temel koşulun bileşkesidir; bu yüzden toplumun genel yaşam koşullarındaki iyileşmeyi hassas biçimde gösterir.'),
  ('Birçok ülkede vergi ve sosyal transferlerden önceki piyasa geliri ile sonraki kullanılabilir gelir için ayrı Gini katsayıları hesaplanır. Bu iki değer genellikle nasıl karşılaştırılır?', 'Kullanılabilir gelirin Gini katsayısı daha düşüktür', ['Kullanılabilir gelirin Gini katsayısı daha yüksektir', 'İki değer her ülkede tam olarak eşittir', 'Piyasa gelirinin Gini katsayısı negatif çıkar'], 'Artan oranlı vergiler ve düşük gelirlilere yapılan transferler gelir farklarını daraltır; bu nedenle kullanılabilir gelir daha eşit dağılır.'),
  ('Ülkelerin çoğunda servet dağılımının gelir dağılımına göre durumu nasıldır?', 'Servet, gelirden çok daha eşitsiz dağılmıştır', ['Servet, gelirden çok daha eşit dağılmıştır', 'İkisinin dağılımı her zaman aynıdır', 'Servet dağılımı hiçbir ülkede ölçülmemekte ve tahmin bile edilmemektedir'], 'Servet, yıllar boyunca biriken tasarruflar, miras ve varlık getirileriyle oluşur; nüfusun önemli bir kısmının çok az ya da negatif serveti olduğundan servet Gini katsayıları gelirinkinden belirgin biçimde yüksektir.'),
  ('Bir ülkede herkesin gelirinin aynı oranda, örneğin yüzde 10 artması Gini katsayısını nasıl etkiler?', 'Değiştirmez', ['Yüzde 10 artırır', 'Yüzde 10 azaltır', 'Sıfıra indirir'], 'Gini katsayısı gelir paylarına dayanır. Herkesin geliri aynı oranda artınca payların hiçbiri değişmez, bu yüzden Gini aynı kalır.'),
  ('ABD\'de 1929-1933 yılları arasında reel GSYH\'nin düşüşü yaklaşık ne büyüklükteydi?', 'Yaklaşık dörtte bir', ['Yaklaşık yüzde 2', 'Yaklaşık yüzde 5', 'Yaklaşık yüzde 75, yani dörtte üç'], 'Büyük Buhran\'da ABD\'nin reel üretimi dört yılda yaklaşık yüzde 25-27 geriledi; bu, modern dönemin en derin daralmasıdır.'),
  ('Çin ekonomisinin 1978\'deki reformlardan sonraki yaklaşık otuz yıl boyunca ulaştığı ortalama yıllık reel büyüme hızı yaklaşık ne kadardı?', 'Yüzde 10 dolayında', ['Yüzde 2 dolayında', 'Yüzde 25 dolayında', 'Yüzde 0, yani durgun'], 'Çin 1978-2010 döneminde yılda ortalama yaklaşık yüzde 10 büyümüş; bu hız GSYH\'nin her yedi yılda bir ikiye katlanması anlamına gelir.'),
  ('2008-2013 döneminde reel GSYH\'si yaklaşık dörtte bir oranında küçülerek gelişmiş bir ülkede savaş dışı dönemde görülen en derin daralmalardan birini yaşayan Avrupa ülkesi hangisidir?', 'Yunanistan', ['Almanya', 'İsveç', 'Polonya'], 'Borç krizi ve sert uyum programlarıyla Yunanistan ekonomisi kriz öncesi düzeyine göre yaklaşık yüzde 25 küçülmüş, işsizlik yüzde 27\'yi aşmıştır.'),
  ('Potansiyel çıktı (potansiyel GSYH) en doğru biçimde nasıl tanımlanır?', 'Kaynaklar sürdürülebilir yoğunlukta kullanıldığında, enflasyonu hızlandırmadan üretilebilecek düzey', ['Ekonominin fiziksel olarak üretebileceği, hiçbir koşulda aşılamayan en yüksek miktar', 'Geçmiş on yılın ortalama nominal GSYH\'si ile bu yılın nominal GSYH\'sinin aritmetik ortalaması', 'Bir ülkenin ihraç edebileceği mal ve hizmetlerin tamamının değeri'], 'Potansiyel çıktı mutlak bir tavan değildir; ekonomi kısa süre onun üzerinde çalışabilir, ancak bu durum enflasyon baskısı yaratır.'),
  ('Bir ekonomide nüfusun hızla yaşlanması ve çalışma çağındaki nüfusun azalması, diğer her şey aynıyken potansiyel büyüme hızını nasıl etkiler?', 'Düşürür', ['Yükseltir', 'Etkilemez', 'Önce sıfıra indirir sonra iki katına çıkarır'], 'Potansiyel büyüme, işgücü artışı ile verimlilik artışının toplamına yakındır. İşgücünün azalması, verimlilik artmadıkça potansiyel büyümeyi aşağı çeker.'),
  ('Say yasası doğru kabul edilirse ekonomi için hangi sonuç çıkar?', 'Genel ve kalıcı bir talep yetersizliği (genel aşırı üretim) olamaz', ['Bütün piyasalarda her zaman arz fazlası bulunur', 'Paranın değeri sürekli artar', 'Tasarruf yapmak her zaman yasaklanmalıdır ve gelirin tamamı tüketime ayrılmalıdır'], 'Üretim, üreticilere aynı değerde gelir sağlar ve bu gelir harcanır. Bu nedenle bazı mallarda fazla olsa bile ekonomi genelinde kalıcı bir talep yetersizliği beklenmez; Keynes bu görüşü eleştirmiştir.'),
  ('Klasik modelde tasarruflar ile yatırımlar arasındaki eşitliği sağlayan değişken hangisidir?', 'Faiz oranı', ['Döviz kuru', 'Vergi oranı', 'İşsizlik oranı'], 'Klasiklere göre ödünç verilebilir fonlar piyasasında faiz, tasarruf arzı ile yatırım talebini eşitler. Keynes ise bu eşitliğin gelir değişmeleriyle sağlandığını savunmuştur.'),
  ('Satın Alma Yöneticileri Endeksi (PMI) gibi anket temelli göstergelerin makroekonomik izlemede değerli görülmesinin temel nedeni hangisidir?', 'GSYH verisinden çok daha erken, ay bitmeden kısa süre sonra yayımlanmaları', ['Resmî GSYH verisinin yerini yasal olarak almaları ve ulusal hesapları geçersiz kılmaları', 'Hiçbir zaman yanılmamaları ve revize edilmemeleri', 'Yalnızca hizmet sektöründeki fiyatları ölçmeleri'], 'GSYH çeyrek bittikten iki ay kadar sonra açıklanırken PMI ilgili ayın hemen ardından yayımlanır; bu nedenle ekonominin yönüne dair erken sinyal verir.'),
  ('Türkiye\'de imalat sanayinin kapasite kullanım oranı istatistiğini hangi kurum yayımlar?', 'Türkiye Cumhuriyet Merkez Bankası', ['Türkiye İstatistik Kurumu', 'Hazine ve Maliye Bakanlığı', 'Borsa İstanbul ve Sermaye Piyasası Kurulu'], 'Kapasite kullanım oranı, TCMB\'nin imalat sanayi firmalarına uyguladığı anketlere dayanılarak her ay yayımlanır.'),
  ('İmalat sanayinde kapasite kullanım oranının uzun dönem ortalamasının belirgin biçimde üzerine çıkması en çok neyi düşündürür?', 'Talebin güçlü olduğunu ve yeni yatırım ile fiyat baskısının artabileceğini', ['Ekonominin derin bir durgunlukta olduğunu', 'Fabrikaların yarısının kapandığını', 'İşsizliğin hızla arttığını ve ücretlerin düştüğünü, talebin ise çöktüğünü'], 'Mevcut kapasite yoğun kullanılıyorsa firmalar yeni yatırıma yönelir; aynı zamanda arz darboğazları fiyatları yukarı itebilir.'),
  ('İstatistik kurumlarının, çeyrek bittikten kısa süre sonra eksik veriye dayanarak açıkladığı ve sonradan revize edilebilen ilk GSYH tahminine ne ad verilir?', 'Öncü tahmin', ['Kesin hesap', 'Baz yılı tahmini', 'Potansiyel çıktı ve uzun dönem eğilimi'], 'Öncü tahminler hız için doğruluktan bir miktar ödün verir; daha fazla veri geldikçe GSYH rakamları düzenli olarak revize edilir.'),
  ('Bir ülkenin \'demografik fırsat penceresi\' döneminde olduğu söylendiğinde ne kastedilir?', 'Çalışma çağındaki nüfusun payının yüksek, bağımlı nüfusun payının düşük olduğu', ['Nüfusun hızla azaldığı ve okulların kapandığı', 'Yaşlı nüfus payının en yüksek düzeye ulaştığı', 'Göçün tamamen durduğu, nüfusun ise sabitlenip hiç değişmediği ve yaşlanmadığı dönem'], 'Bu dönemde üreten nüfus oranı yüksektir; doğru politikalarla tasarruf, yatırım ve büyüme için önemli bir avantaj (demografik temettü) sağlanabilir.'),
  ('Demografik fırsat penceresinin büyümeye katkıya dönüşebilmesi için hangi koşul en önemlidir?', 'Artan çalışma çağı nüfusuna yeterli ve verimli iş yaratılması', ['Doğum oranlarının yeniden hızla artması', 'Okullaşma oranının düşürülmesi', 'Emeklilik yaşının indirilmesi ve işgücüne katılımın bilinçli olarak azaltılması'], 'Çalışma çağındaki nüfus iş bulamazsa fırsat yüksek işsizliğe dönüşebilir. Eğitim ve istihdam politikaları demografik temettünün gerçekleşmesini belirler.'),
  ('Gelişmiş ülkelerde nüfusun yaşlanmasının makroekonomik açıdan en belirgin sonuçlarından biri hangisidir?', 'İşgücü artışının yavaşlaması ve potansiyel büyümenin düşmesi', ['Çalışan başına düşen emekli sayısının azalması', 'Sağlık harcamalarının kendiliğinden gerilemesi', 'İşgücüne katılma oranının otomatik olarak yükselmesi ve yüzde yüze ulaşması'], 'Yaşlanma, çalışan nüfusun payını düşürür; aynı işgücüyle daha büyük bir bağımlı nüfusa bakılması gerekir ve potansiyel büyüme zayıflar.'),
  ('Ulusal gelir hesapları ve ekonomik büyümenin ampirik ölçümü alanındaki çalışmaları nedeniyle Nobel İktisat Ödülü\'nü 1971\'de alan iktisatçı kimdir?', 'Simon Kuznets', ['Paul Samuelson', 'Milton Friedman', 'Wassily Leontief'], 'Kuznets, ulusal gelirin sistematik ölçümüne ve büyümenin uzun dönemli ampirik analizine yaptığı katkılarla 1971\'de ödüllendirilmiştir.'),
  ('Bir ülkenin yerel para cinsinden reel GSYH\'si yüzde 3 artarken aynı yıl ulusal para dolar karşısında sert değer kaybettiyse, dolar cinsinden GSYH için ne söylenebilir?', 'Reel büyümeye rağmen azalmış olabilir', ['Mutlaka yüzde 3 artmıştır', 'Kur değişiminden hiç etkilenmez', 'Mutlaka iki katına çıkmıştır ve büyümüştür'], 'Dolar cinsinden GSYH, yerel para değerinin kura bölünmesiyle bulunur. Kurdaki sert artış, üretim artışına rağmen dolar cinsinden büyüklüğü düşürebilir.'),
  ('Nominal GSYH\'nin reel GSYH\'ye bölünmesiyle dolaylı olarak elde edildiği için GSYH deflatörüne başka hangi ad verilir?', 'Zımni (örtük) fiyat deflatörü', ['Çekirdek enflasyon endeksi', 'Üretici fiyat endeksi', 'Laspeyres sepet endeksi ve TÜFE'], 'Deflatör doğrudan bir fiyat anketiyle değil, iki GSYH ölçüsünün oranından hesaplandığı için zımni fiyat deflatörü olarak da adlandırılır.'),
  ('Makroekonomide \'kısa dönem\' ile \'uzun dönem\' ayrımının temel ölçütü hangisidir?', 'Ücret ve fiyatların tam uyum sağlamaya yetecek zamanı bulup bulmadığı', ['Takvimde tam olarak bir yıl geçip geçmediği', 'Seçimlerin yapılıp yapılmadığı', 'Borsanın açık ya da kapalı olduğu ve günlük işlem saatlerinin uzunluğu'], 'Kısa dönemde bazı ücret ve fiyatlar katıdır, bu yüzden talep değişimleri üretimi etkiler. Uzun dönemde fiyatlar tam esneklik kazanır ve üretim arz koşullarıyla belirlenir.'),
  ('İşsizlerin iş bulma hızını artıran gelişmeler, işgücü akımları yaklaşımına göre doğal işsizlik oranını nasıl etkiler?', 'Düşürür', ['Yükseltir', 'Etkilemez', 'Önce sıfıra indirir sonra ikiye katlar'], 'Doğal oran s / (s + f) ile yaklaşıklanır. İş bulma oranı (f) büyüdükçe kesir küçülür, yani doğal oran düşer.'),
  ('Bir miktar friksiyonel işsizliğin ekonomi için yararlı sayılabilmesinin nedeni hangisidir?', 'İş arayanların becerilerine daha uygun işler bulmasına zaman tanıması', ['Ücretlerin sürekli düşmesini sağlaması', 'Devletin vergi gelirlerini artırması', 'Firmaların üretimi durdurmasına yol açması ve stokları eritmesi'], 'İnsanların ilk teklifi hemen kabul etmek yerine uygun işi araması, emeğin daha verimli kullanılmasını sağlayan daha iyi eşleşmeler doğurur.'),
  ('Tarih boyunca yeni teknolojiler bazı meslekleri ortadan kaldırmıştır. İktisatçıların çoğunun bu konudaki uzun dönem gözlemi hangisidir?', 'Yeni sektörler ve meslekler doğduğu için toplam istihdam kalıcı olarak çökmemiştir', ['Her teknolojik yenilik işsizliği kalıcı olarak artırmıştır', 'Teknoloji hiçbir mesleği etkilememiştir', 'Teknolojik ilerleme her ülkede çalışma çağındaki nüfusu azaltmış ve işgücünü küçültmüştür'], 'Tarım makineleşirken ve fabrikalar otomasyona geçerken yeni sanayi ve hizmet işleri doğmuştur. Ancak geçiş döneminde bazı gruplar ciddi kayıplar yaşayabilir.'),
  ('Uzun yıllar boyunca GSYH\'sinin yaklaşık yüzde 40\'ından fazlasını tasarruf ederek dünyanın en yüksek ulusal tasarruf oranlarından birine sahip olan büyük ekonomi hangisidir?', 'Çin', ['ABD', 'Birleşik Krallık', 'Brezilya'], 'Çin\'de hanehalkı, şirket ve kamu tasarrufları birlikte çok yüksek bir ulusal tasarruf oranı oluşturmuş ve bu, yüksek yatırım oranını finanse etmiştir.'),
  ('Şirketlerin elde ettikleri kârın ortaklarına dağıtmadıkları kısmı ulusal tasarruf içinde hangi bileşene dâhil edilir?', 'Özel tasarrufa', ['Kamu tasarrufuna', 'Yabancı tasarrufa', 'Hiçbir tasarrufa girmez ve tüketim sayılır'], 'Dağıtılmayan kârlar firmaların yaptığı tasarruftur ve hanehalkı tasarrufuyla birlikte özel kesim tasarrufunu oluşturur.'),
  ('Durgunluk başladığında firmaların yeni sipariş vermeden önce depolarındaki malları eritmeye çalışması GSYH\'nin hangi bileşenini doğrudan düşürür?', 'Stok yatırımlarını', ['Kamu harcamalarını', 'Transfer ödemelerini', 'Hanehalkının hizmet tüketimini'], 'Stokların azalması negatif stok yatırımı demektir. Bu dönemlerde üretim satışların altına iner; stok döngüleri kısa dalgalanmalarda önemli rol oynar.'),
  ('İkinci Dünya Savaşı sonrası ABD verilerinde genişleme ve daralma dönemlerinin ortalama uzunlukları karşılaştırıldığında ne görülür?', 'Genişlemeler, daralmalardan çok daha uzun sürmüştür', ['Daralmalar, genişlemelerden çok daha uzun sürmüştür', 'İkisi her seferinde tam olarak aynı süredir', 'Hiç daralma yaşanmamış, yalnızca genişleme görülmüştür'], 'NBER verilerine göre savaş sonrası genişlemeler ortalama beş yılı aşarken daralmalar ortalama bir yıldan kısa sürmüştür.'),
  ('Konjonktür dalgalanmalarının matematiksel bir dalga gibi düzenli aralıklarla tekrarlanmaması ne anlama gelir?', 'Genişleme ve daralmaların süresi ve derinliği her seferinde farklı olur', ['Ekonomide hiçbir zaman daralma yaşanmaz', 'Dalgalanmalar tam olarak her dört yılda bir yaşanır', 'Konjonktür yalnızca tarım ekonomilerinde görülür ve sanayi ile hizmetler ağırlıklı ekonomilerde görülmez'], '\'Konjonktür döngüsü\' adına karşın dalgalanmalar düzensizdir; bu yüzden bir sonraki resesyonun zamanını kesin olarak tahmin etmek zordur.'),
  ('Büyük bir depremin fabrikaları, yolları ve limanları ağır biçimde tahrip etmesi uzun dönem toplam arzı nasıl etkiler?', 'Sola kaydırır; üretim kapasitesi azalır', ['Sağa kaydırır; üretim kapasitesi artar', 'Etkilemez; yalnızca toplam talebi değiştirir', 'Dikeyden yataya çevirir ve fiyatları sabitler'], 'Sermaye stokunun yok olması potansiyel üretimi düşürür. Yeniden yapım harcamaları talebi artırsa da kayıp kapasite ancak zamanla yerine konabilir.'),
  ('İşçiler ve firmalar gelecek yıl fiyat düzeyinin önemli ölçüde artacağını beklemeye başlarsa kısa dönem toplam arz eğrisi nasıl etkilenir?', 'Sola kayar', ['Sağa kayar', 'Değişmez', 'Uzun dönem eğrisiyle birlikte sağa döner'], 'Beklenen fiyat artışı ücret taleplerine ve fiyatlama kararlarına yansır; maliyetler yükseldiği için her fiyat düzeyinde daha az üretilir.'),
  ('Klasik yaklaşım ile Keynesyen yaklaşım kısa dönem toplam arz eğrisinin biçimi konusunda nasıl ayrışır?', 'Klasikler eğriyi dikey, Keynesyenler yatay ya da pozitif eğimli görür', ['Klasikler eğriyi yatay, Keynesyenler dikey görür', 'İkisi de eğriyi negatif eğimli çizer', 'İki yaklaşım da toplam arz kavramını reddeder ve modellerinde hiç kullanmaz'], 'Klasiklere göre esnek fiyatlar sayesinde üretim hep potansiyelde kalır. Keynesyenlere göre ise kısa dönemde fiyatlar katıdır ve talep üretimi belirler.'),
  ('Ekonominin genişleme evresinde ithalatın genellikle nasıl davrandığı ve bunun nedeni hangisidir?', 'Artar; gelir yükseldikçe yabancı mallara harcama da artar', ['Azalır; gelir yükselince tüketiciler yalnızca yerli malları tercih eder', 'Değişmez; ithalat gelirden bağımsızdır', 'Sıfıra iner; genişlemede dış ticaret durur'], 'İthalat gelire bağlıdır. Bu nedenle genişlemelerde artar, daralmalarda azalır; net ihracat bu yüzden çoğu zaman konjonktür karşıtı hareket eder.'),
  ('1960 dolaylarında kişi başı geliri Gana gibi Afrika ülkeleriyle benzer düzeyde olan, ancak sonraki onlarca yılda çok hızlı büyüyerek yüksek gelirli ülkeler arasına giren Asya ülkesi hangisidir?', 'Güney Kore', ['Afganistan', 'Myanmar', 'Kuzey Kore'], 'Güney Kore\'nin Gana ile karşılaştırması kalkınma iktisadında sık kullanılır; iki ülkenin yollarının ayrışması yatırım, eğitim, ihracat ve kurumların önemine işaret eder.'),
  ('Kişi başı geliri yılda yüzde 1 artan bir ülke ile yüzde 3 artan bir ülke karşılaştırılıyor. 50 yılın sonunda kişi başı gelir başlangıç düzeyinin yaklaşık kaç katına çıkar?', 'Birincisinde yaklaşık 1,6 kat, ikincisinde yaklaşık 4,4 kat', ['Birincisinde 1,5 kat, ikincisinde 2,5 kat', 'Birincisinde 2 kat, ikincisinde 6 kat', 'İkisinde de yaklaşık 3 kat, çünkü ortalama büyüme aynıdır'], 'Bileşik büyümeyle 1,01⁵⁰ ≈ 1,64 ve 1,03⁵⁰ ≈ 4,38 olur. Yıllık büyümedeki küçük farklar uzun dönemde yaşam standartlarında çok büyük farklara dönüşür.'),
  ('Dünyanın bütün ülkeleri bir arada incelendiğinde yoksul ülkelerin zenginlerden sistemli olarak daha hızlı büyüdüğü yönündeki \'mutlak yakınsama\' görüşü için ampirik bulgular genellikle ne gösterir?', 'Dünya genelinde güçlü bir mutlak yakınsama gözlenmez', ['Bütün yoksul ülkeler zenginleri yakalamıştır', 'Zengin ülkeler her zaman yoksullardan hızlı büyümüştür ve fark hep açılmıştır', 'Ülkeler arasında hiçbir büyüme farkı yoktur'], 'Yakınsama, tasarruf, nüfus artışı ve kurumları benzer olan ülke grupları arasında (koşullu olarak) daha belirgindir; dünya geneli için mutlak yakınsama zayıftır.'),
  ('Gelişmekte olan ülkelerin, gelişmiş ülkelerde zaten bulunmuş teknolojileri benimseyerek onlardan daha hızlı büyüyebilmesi hangi avantajla açıklanır?', 'Teknolojiyi sıfırdan icat etmek yerine aktarabilmeleri', ['Daha yüksek nüfusa sahip olmaları', 'Hiç sermayeye ihtiyaç duymamaları', 'Dış ticarete tamamen kapalı olmaları ve rekabetten korunmaları'], 'Teknoloji sınırındaki ülkeler büyümek için yenilik yapmak zorundadır; geride olanlar ise mevcut bilgiyi taklit ve aktarım yoluyla daha ucuza ve hızlı benimseyebilir.'),
  ('Çin\'de 1980\'lerden itibaren mutlak yoksulluk içinde yaşayan insan sayısının yüz milyonlarca azalmasının temel nedeni olarak en çok hangisi gösterilir?', 'Uzun süreli hızlı ekonomik büyüme', ['Nüfusun yarıya inmesi', 'Bütün gelirlerin eşit dağıtılması', 'İhracatın tamamen yasaklanması ve kapalı ekonomiye dönülmesi'], 'Onlarca yıl süren yüksek büyüme, kırsaldan kentlere ve sanayiye geçişle birlikte gelirleri artırmış; bu, tarihteki en büyük yoksulluk azalması olarak kabul edilir.'),
  ('Bir ülkenin yıllık büyüme hızı üç yıl boyunca sırasıyla yüzde 2, yüzde 4 ve yüzde 6 olmuştur. Üç yıllık toplam büyüme yaklaşık yüzde kaçtır?', '12,4', ['12', '48', '4'], 'Büyüme oranları çarpılarak birleşir: 1,02 × 1,04 × 1,06 ≈ 1,1245. Toplam büyüme yaklaşık yüzde 12,4\'tür; oranları toplamak (yüzde 12) bileşik etkiyi gözden kaçırır.'),
  ('GSYH\'si 1.000 milyar dolar olan A ülkesi yüzde 2, GSYH\'si 200 milyar dolar olan B ülkesi yüzde 8 büyümüştür. Mutlak üretim artışı hangi ülkede daha büyüktür?', 'A ülkesinde (20 milyar dolar)', ['B ülkesinde (16 milyar dolar)', 'İkisinde eşittir', 'B ülkesinde (80 milyar dolar)'], 'A\'nın artışı 1.000 × 0,02 = 20, B\'ninki 200 × 0,08 = 16 milyar dolardır. Yüksek büyüme oranı, küçük bir tabanda daha az mutlak artış anlamına gelebilir.'),
  ('Açık ekonomi analizinde tüketim, yatırım ve kamu harcamalarının toplamı olan \'yurt içi talep\' (absorpsiyon) GSYH\'den büyükse ne söylenebilir?', 'Ülke ürettiğinden fazlasını harcamaktadır ve net ihracatı negatiftir', ['Ülke ürettiğinin tamamını ihraç etmektedir', 'Ülkenin net ihracatı pozitiftir', 'Ülkede hiç ithalat yapılmamaktadır ve ekonomi tamamen kapalı bir yapıdadır'], 'GSYH = yurt içi talep + net ihracat olduğundan, yurt içi talebin GSYH\'yi aşması net ihracatın negatif olmasını, yani farkın ithalatla karşılanmasını gerektirir.'),
  ('Gayrisafi milli harcanabilir gelir, GSMH\'ye hangi kalem eklenerek bulunur?', 'Yurt dışından alınan net cari transferler', ['Amortisman', 'Dolaylı vergiler', 'Stok değişimi ve ara mallar ile yurt içi ürün vergileri'], 'Yurt dışında yaşayan aile üyelerinin karşılıksız gönderdiği paralar üretim karşılığı olmadığından GSMH\'de yer almaz, ama ülkenin harcayabileceği geliri artırır.'),
  ('Türkiye\'de tarımın toplam istihdamdaki payı, GSYH\'deki payından belirgin biçimde yüksektir. Bu durum en çok neyi gösterir?', 'Tarımda çalışan başına katma değerin ekonomi ortalamasından düşük olduğunu', ['Tarımda verimliliğin bütün sektörlerden yüksek olduğunu', 'Tarım ürünlerinin GSYH\'ye hiç dâhil edilmediğini', 'Tarımda çalışanların tamamının kayıtlı ve sigortalı olduğunu, diğer sektörlerde ise kayıt dışılığın yaygın olduğunu'], 'İstihdamın büyük bir kısmını kullanan bir sektör üretimin daha küçük bir kısmını yaratıyorsa, o sektörde işçi başına üretim ortalamanın altındadır.'),
  ('Uzun dönemde bir ülkede ortalama reel ücretlerin yükselmesini en çok hangi etken belirler?', 'Emek verimliliğindeki artış', ['Para arzındaki artış', 'Nominal ücretlerin yasayla artırılması', 'Döviz kurunun yükselmesi ve ithalatın pahalanması'], 'Firmalar uzun dönemde çalışanlara ürettikleri değerle uyumlu ücret ödeyebilir. Verimlilik artmadan yapılan nominal artışlar fiyatlara yansıyarak reel kazanç sağlamaz.'),
  ('\'İşsizliği azaltmak için herkes daha az saat çalışsın, böylece işler paylaşılır\' görüşünün dayandığı ve iktisatçıların yanıltıcı bulduğu varsayım hangisidir?', 'Ekonomideki toplam iş miktarının sabit olduğu', ['İşgücünün her yıl ikiye katlandığı', 'Ücretlerin hiçbir zaman değişmediği', 'Teknolojinin hiç gelişmediği ve verimliliğin sabit kaldığı'], 'Bu \'sabit iş miktarı yanılgısı\' olarak bilinir. Oysa iş miktarı talep, verimlilik ve ücretlere göre değişir; daha fazla çalışan daha fazla gelir ve harcama da yaratır.'),
  ('1980\'lerden bu yana birçok gelişmiş ülkede milli gelirde emeğin (ücretlerin) payının ne yönde değiştiği gözlenmiştir?', 'Azalma eğiliminde olduğu', ['Sürekli ve hızla arttığı', 'Tam olarak sabit kaldığı', 'Yüzde yüze ulaştığı ve kârların ortadan kalktığı'], 'Pek çok çalışma, teknolojik değişim, küreselleşme ve piyasa yoğunlaşması gibi etkenlerle emek payının birçok ülkede gerilediğini göstermektedir.'),
  ('Gelirin zenginlere doğru yoğunlaşması, Keynesyen bakış açısıyla toplam tüketimi neden zayıflatabilir?', 'Yüksek gelirlilerin marjinal tüketim eğilimi düşük olduğu için', ['Zenginler gelirlerinin tamamını harcadığı için', 'Yoksulların tasarruf oranı çok yüksek olduğu için', 'Gelir dağılımının tüketimi hiçbir şekilde etkilemediği ve yalnızca fiyatların önemli olduğu için'], 'Aynı toplam gelir, ek gelirin büyük kısmını tasarruf eden gruplarda toplanırsa harcanan pay küçülür ve toplam talep zayıflar.'),
  ('Potansiyel GSYH\'nin her yıl 100 birim olduğu bir ekonomide bir resesyon nedeniyle üç yıl üst üste 97, 98 ve 99 birim üretilmiştir. Toplam üretim kaybı, bir yıllık potansiyelin yüzde kaçıdır?', '6', ['3', '1', '9'], 'Her yılın açığı 3, 2 ve 1 birimdir; toplam 6 birim kayıp bir yıllık potansiyelin (100) yüzde 6\'sıdır. Resesyonun maliyeti yalnızca en kötü yılla değil, toplam açıkla ölçülür.'),
  ('Tüketicilerin bir resesyon geleceğinden korkup harcamalarını kısması, firmaların da buna yanıt olarak yatırımı ve istihdamı azaltmasıyla gerçekten bir resesyon yaşanması hangi kavramla açıklanır?', 'Kendi kendini gerçekleştiren beklentiler', ['Rasyonel beklentiler altında yansızlık', 'Uyarlayıcı beklentiler ve geçmiş enflasyon', 'Ricardo denkliği'], 'Kötümser beklentiler harcamayı azaltarak tam da korkulan sonucu üretebilir; Keynes de güvenin talep üzerindeki etkisini vurgulamıştır.'),
  ('Devletin borçlandığı tahvillerin sahiplerine ödediği faizler, harcama yöntemiyle GSYH hesaplanırken kamu harcaması kalemine neden dâhil edilmez?', 'Cari bir mal ya da hizmet alımının karşılığı olmadığı için', ['Faizler vergiden muaf olduğu için', 'Faizler her zaman yabancılara ödendiği için', 'Faizler yatırım kalemine aktarıldığı ve orada sayıldığı için'], 'Kamu borç faizleri, devletin o dönemde üretilen bir mal ya da hizmeti satın alması değildir; bu nedenle transfer niteliğinde değerlendirilir.'),
  ('Hanehalklarının tüketim harcamaları, ekonomik dalgalanmalar boyunca toplam gelirle karşılaştırıldığında genellikle nasıl davranır?', 'Gelirden daha az dalgalanır', ['Gelirden çok daha fazla dalgalanır', 'Gelirle ters yönde hareket eder', 'Gelirle hiçbir ilişki göstermez'], 'Haneler tüketimlerini zaman içinde düzgün tutmaya çalışır; geçici gelir düşüşlerinde birikimlerini kullanır. Bu yüzden toplam tüketim, gelirden ve özellikle yatırımdan daha istikrarlıdır.'),
  ('Basit Keynesyen modelde marjinal tasarruf eğilimi sıfır olsaydı, yani ek gelirin tamamı harcansaydı, çarpan için ne söylenebilirdi?', 'Sınırsız büyük olurdu', ['Sıfır olurdu', 'Tam olarak 1 olurdu', 'Negatif olurdu'], 'Çarpan 1 / MTasE\'dir; payda sıfıra yaklaştıkça çarpan sınırsız büyür. Gerçekte tasarruf, vergi ve ithalat sızıntıları çarpanı sınırlar.'),
  ('Avro bölgesi borç krizi sırasında, 2013\'te genel işsizlik oranı yüzde 25\'i, genç işsizlik oranı ise yüzde 50\'yi aşan büyük Avrupa ekonomisi hangisidir?', 'İspanya', ['Almanya', 'Hollanda', 'Avusturya'], 'İspanya\'da konut balonunun sönmesi ve borç krizi inşaat ağırlıklı ekonomide istihdamı çökertmiş; işsizlik 2013\'te yüzde 26 dolayında zirve yapmıştır.'),
  ('ABD\'de 2008 krizinin ardından işsizlik oranı Ekim 2009\'da hangi düzeyde zirve yapmıştır?', 'Yaklaşık yüzde 10', ['Yaklaşık yüzde 4', 'Yaklaşık yüzde 25', 'Yaklaşık yüzde 50'], 'Büyük Durgunluk sırasında ABD\'de işsizlik oranı Ekim 2009\'da yüzde 10,0 ile zirveye ulaşmış ve uzun bir düşüş sürecine girmiştir.'),
  ('ABD\'de COVID-19 salgınının başladığı 2020 baharında aylık işsizlik oranı hangi düzeye kadar yükselmiştir?', 'Yaklaşık yüzde 15', ['Yaklaşık yüzde 5', 'Yaklaşık yüzde 40', 'Yaklaşık yüzde 2'], 'Kapanmalarla birlikte Nisan 2020\'de işsizlik oranı yaklaşık yüzde 15\'e fırlamış, ancak sonraki aylarda hızla gerilemiştir.'),
  ('BM\'nin 2000 yılında kabul ettiği ve 2015\'e kadar aşırı yoksulluğu yarıya indirmeyi de hedefleyen kalkınma çerçevesinin adı nedir?', 'Binyıl Kalkınma Hedefleri', ['Sürdürülebilir Kalkınma Amaçları', 'Washington Uzlaşısı', 'Kyoto Protokolü ve Paris Anlaşması'], 'Sekiz maddeden oluşan Binyıl Kalkınma Hedefleri 2015\'te sona ermiş ve yerini 17 maddelik Sürdürülebilir Kalkınma Amaçları\'na bırakmıştır.'),
  ('Bir ülkede yıllık tüketim harcamaları 700, gelir 1.000 milyar liradır. Gelir 1.100\'e çıkınca tüketim 760 olmuştur. Yeni gelir düzeyinde ortalama tüketim eğilimi ile marjinal tüketim eğilimi hangisidir?', 'OTE ≈ 0,69; MTE = 0,6', ['OTE = 0,7; MTE = 0,7', 'OTE = 0,6; MTE ≈ 0,69', 'OTE ≈ 0,76; MTE = 0,06'], 'OTE = 760 / 1.100 ≈ 0,69. MTE = (760 − 700) / (1.100 − 1.000) = 60 / 100 = 0,6. Ortalama ve marjinal eğilim farklı kavramlardır.'),
  ('Bir resesyonda gelir düşerken hanehalklarının tasarruflarını azaltarak tüketimlerini korumaya çalışması, ortalama tüketim eğilimini nasıl etkiler?', 'Yükseltir', ['Düşürür', 'Değiştirmez', 'Sıfıra indirir'], 'Gelir azalırken tüketim daha az azalırsa C / Y oranı büyür; yani gelirin daha büyük bir kısmı tüketilir.'),
  ('Friksiyonel, yapısal ve konjonktürel işsizlik süre bakımından karşılaştırıldığında, genellikle en uzun süren ve çözümü en zor olan tür hangisidir?', 'Yapısal işsizlik', ['Friksiyonel işsizlik', 'Mevsimlik işsizlik', 'Konjonktürel işsizlik'], 'Yapısal işsizlikte işsizlerin becerileri ya da bulundukları bölge boş işlere uymaz; yeni beceri kazanmak veya taşınmak zaman aldığından bu işsizlik uzun sürer.'),
  ('Sanayi öncesi toplumlarda verimlilik artışlarının kalıcı bir refah artışı yerine nüfus artışıyla emilmesi ve kişi başı gelirin geçimlik düzeye geri dönmesi hangi kavramla anlatılır?', 'Malthus tuzağı', ['Likidite tuzağı', 'Orta gelir tuzağı', 'Borç tuzağı'], 'Gelir arttığında nüfus da arttığı ve toprak sınırlı olduğu için kişi başı gelir yeniden düşer. Sanayi Devrimi ve demografik dönüşüm bu tuzaktan çıkışı sağlamıştır.'),
  ('Bir ülkenin GSYH\'si 1.000 milyar lira, nüfusu 50 milyondur. Satın alma gücü paritesine göre 5 lira 1 uluslararası dolara eşittir. Kişi başı GSYH SAGP cinsinden kaç uluslararası dolardır?', '4.000', ['20.000', '1.000', '100'], 'Kişi başı GSYH 1.000.000.000.000 / 50.000.000 = 20.000 liradır. SAGP oranına bölününce 20.000 / 5 = 4.000 uluslararası dolar bulunur.'),
  ('Bir ekonomide bir yılda üretim 1.000 milyar lira, planlanan toplam harcama ise 950 milyar liradır. Bu durumda firmaların depolarında ne olur?', '50 milyar liralık planlanmamış stok birikir', ['Stoklar 50 milyar lira azalır', 'Stoklar değişmez', '1.950 milyar liralık stok birikir ve üretim ikiye katlanır'], 'Üretilen ancak planlanan harcamayla satın alınmayan 50 milyar liralık mal stoklarda kalır. Firmalar sonraki dönemde üretimi azaltma eğilimine girer.'),
  ('Bir ülkede ekonomi genelinde boş iş ilanları ve işsizler aynı anda bol miktarda bulunuyorsa, bu durum en çok hangi işsizlik türüne işaret eder?', 'Yapısal işsizlik', ['Konjonktürel işsizlik', 'Gizli işsizlik', 'Gönüllü işsizlik ve emeklilik'], 'Talep yetersizliği olsaydı boş iş de az olurdu. Hem işsiz hem boş kadro bolluğu, işsizlerle işler arasında beceri ya da yer uyumsuzluğu olduğunu düşündürür.'),
  ('Türkiye\'de işsizlik oranı haberlerinde çoğunlukla \'mevsim etkisinden arındırılmış\' oranın kullanılmasının nedeni hangisidir?', 'Tarım ve turizm gibi işlerin yıl içindeki düzenli iniş çıkışlarının eğilimi gizlememesi', ['Arındırılmış oranın her zaman daha düşük çıkması', 'Ham verinin yalnızca yılda bir kez derlenmesi', 'Mevsimlik işçilerin istatistiklerden tamamen çıkarılması ve sayılmaması'], 'İşsizlik kışın tarım ve inşaatta, yazın turizmde düzenli olarak değişir. Arındırılmış seri, ardışık aylar karşılaştırılırken bu takvim etkisini ayıklar; mevsimlik çalışanlar yine istatistiğe dâhildir.'),
  ('Makroekonomide \'toplulaştırma\' (agregasyon) yapılması ne anlama gelir?', 'Milyonlarca bireysel kararın ve fiyatın toplam büyüklüklerle özetlenmesi', ['Bütün firmaların tek bir firmada birleştirilmesi', 'Bütün vergilerin tek bir vergide toplanması', 'Ülkelerin ortak para birimine geçmesi ve tek bir merkez bankası kurması'], 'Makroekonomi tek tek malların yerine toplam üretim, genel fiyat düzeyi ve toplam istihdam gibi büyüklüklerle çalışır; bu, bireysel verilerin toplulaştırılmasıyla mümkündür.'),
  ('İktisatçıların \'reel\' ve \'nominal\' değişken ayrımında aşağıdakilerden hangisi reel bir değişkendir?', 'Bir işçinin saatlik ücretiyle alabildiği ekmek sayısı', ['Bir işçinin lira cinsinden ifade edilen saatlik brüt ücreti', 'Cari fiyatlarla GSYH', 'Bir ekmeğin lira cinsinden fiyatı'], 'Reel değişkenler fiziksel miktarlar ya da göreli fiyatlarla ölçülür. Ücretle alınabilen ekmek sayısı reel ücrettir; lira cinsinden büyüklükler nominaldir.'),
  ('Türkiye\'de 2001 krizinden sonra ekonominin 2002-2007 döneminde izlediği büyüme seyri için hangisi doğrudur?', 'Her yıl pozitif ve çoğunlukla yüksek büyüme yaşanmıştır', ['Her yıl daralma yaşanmıştır', 'Ekonomi bu dönemde hiç büyümemiştir', 'Yalnızca 2002\'de büyüme olmuş, sonraki yıllarda sürekli küçülme yaşanmıştır'], 'Kriz sonrası toparlanmayla birlikte Türkiye ekonomisi 2002-2007 arasında her yıl büyümüş, bu dönemde ortalama büyüme yüzde 6\'nın üzerinde gerçekleşmiştir.'),
  ('Bir ekonomist \'Bu yıl işsizlik oranı yüzde 9\'dan yüzde 8\'e düştü\' dediğinde bu ifade için hangisi doğrudur?', 'İşsizlik oranı 1 puan, yaklaşık yüzde 11 oranında azalmıştır', ['İşsizlik oranı yüzde 1 oranında azalmıştır', 'İşsizlik oranı 8 puan azalmıştır', 'İşsiz sayısı tam olarak yüzde 1 azalmış ve istihdam aynı kalmıştır'], 'Oranlardaki değişim \'puan\' olarak ifade edilir: 9 − 8 = 1 puan. Göreli değişim ise 1 / 9 ≈ yüzde 11\'dir. Puan ile yüzde değişimi karıştırmamak gerekir.'),
  ('Bir ekonomide gerçekleşen işsizlik oranı yüzde 4, doğal işsizlik oranı yüzde 5 olarak tahmin ediliyorsa konjonktürel işsizlik için ne söylenebilir?', 'Eksi 1 puandır; ekonomi potansiyelinin üzerinde çalışmaktadır', ['Artı 1 puandır; ekonomi derin bir durgunluktadır', 'Yüzde 9\'dur; iki oran toplanarak bulunur', 'Tanım gereği sıfırdır; konjonktürel işsizlik hiçbir zaman negatif olamaz ve hesaplanamaz'], 'Konjonktürel işsizlik gerçekleşen oran ile doğal oranın farkıdır: 4 − 5 = −1. Negatif değer işgücü piyasasının sıkıştığını ve enflasyon baskısının artabileceğini gösterir.'),
  ('Bir ülkede bir yılda 300 milyar liralık net yatırım yapılmış ve GSYH 60 milyar lira artmıştır. Marjinal sermaye-hasıla oranı (ICOR) kaçtır?', '5', ['0,2', '360', '240'], 'ICOR = ΔK / ΔY = 300 / 60 = 5. Bir birimlik ek üretim için beş birim ek sermaye gerekmiştir.'),
  ('İki ülkeden birinde marjinal sermaye-hasıla oranı (ICOR) 3, diğerinde 6\'dır. Bu fark en çok neyi düşündürür?', 'İkinci ülkede yatırımların üretime dönüşme verimliliğinin daha düşük olduğunu', ['İkinci ülkenin daha hızlı büyüdüğünü', 'İki ülkenin yatırım verimliliğinin aynı olduğunu, yalnızca para birimlerinin farklı olduğunu gösterir', 'Birinci ülkenin hiç yatırım yapmadığını ve büyümediğini'], 'Yüksek ICOR, aynı üretim artışı için daha fazla yatırım gerektiğini, yani sermayenin daha az verimli kullanıldığını gösterir.'),
  ('ABD\'de her hafta açıklanan \'ilk kez işsizlik sigortası başvurusu\' sayısı makroekonomistler tarafından neden yakından izlenir?', 'İşgücü piyasasındaki bozulmayı çok hızlı yansıttığı için', ['Enflasyonu doğrudan ölçtüğü için', 'GSYH\'nin resmî hesaplamasında tek kaynak olduğu için', 'Faiz oranlarını otomatik olarak belirlediği ve merkez bankasını bağladığı için'], 'Haftalık başvurular, işten çıkarmalardaki artışı aylık verilerden önce gösterdiği için resesyonların erken sinyallerinden biri kabul edilir.'),
  ('Hisse senedi piyasalarının genel endeksi neden konjonktürün öncü göstergeleri arasında sayılır?', 'Yatırımcıların gelecekteki kâr beklentilerini fiyatlara önceden yansıtması nedeniyle', ['Borsa endeksinin GSYH\'ye birebir eşit olması nedeniyle', 'Borsanın yalnızca geçmiş verileri yansıtması ve geleceğe ilişkin hiçbir bilgi taşımaması nedeniyle', 'Hisse fiyatlarının hiçbir zaman değişmemesi ve tamamen sabit kalması nedeniyle'], 'Fiyatlar beklenen kârlara göre belirlendiğinden borsa çoğu zaman ekonomideki değişimi önceden fiyatlar; ancak yanlış sinyal de verebilir.'),
  ('Aşağıdakilerden hangisi genellikle eşzamanlı bir konjonktür göstergesi kabul edilir?', 'Sanayi üretimi', ['Ortalama işsizlik süresi', 'Yeni inşaat izinleri', 'Hisse senedi endeksi'], 'Sanayi üretimi ekonomik faaliyetle aynı anda iner ve çıkar. İnşaat izinleri ile borsa öncü, işsizlik süresi ise gecikmeli göstergelerdendir.'),
  ('Ulusal hesaplarda devletin yaptığı harcamaların hangi bölümü yatırım (sabit sermaye oluşumu) olarak sınıflanır?', 'Yol, köprü ve hastane binası gibi kalıcı varlıkların yapımı', ['Memur maaşları', 'Kırtasiye ve elektrik giderleri', 'Emekli aylıkları, burslar ve öteki sosyal yardım ödemeleri'], 'Kamu kesiminin uzun süre kullanılacak varlıklar için yaptığı harcamalar sabit sermaye oluşumuna girer; maaşlar ve günlük giderler kamu tüketimidir, transferler ise hiçbirine girmez.'),
  ('Bir ülkede bütün hanelerin geliri aynı oranda iki katına çıkarsa, ortanca gelirin yüzde 60\'ına göre tanımlanan göreli yoksulluk oranı nasıl değişir?', 'Değişmez', ['Yarıya iner', 'Sıfıra iner', 'İki katına çıkar'], 'Göreli yoksulluk sınırı ortanca gelire bağlıdır. Herkesin geliri aynı oranda artınca sınır da aynı oranda yükselir ve sınırın altında kalanların payı değişmez. Mutlak yoksulluk ise azalır.'),
  ('Bireylerin doğdukları aile, cinsiyet ve bölge gibi kendi seçimleri dışındaki koşullar nedeniyle farklı yaşam şanslarına sahip olmasını anlatan kavram hangisidir?', 'Fırsat eşitsizliği', ['Sonuç eşitsizliği', 'Fonksiyonel gelir dağılımı', 'Yatay eşitlik ve dikey eşitlik'], 'Fırsat eşitsizliği, gelir farklarının çabadan değil, kişinin denetiminde olmayan başlangıç koşullarından kaynaklanan kısmına odaklanır.'),
  ('Bir firma Aralık 2023\'te ürettiği makineleri yurt dışına göndermiş, ödemeyi ise Şubat 2024\'te almıştır. Bu ihracat hangi yılın GSYH\'sinde yer alır?', '2023', ['2024', 'İki yıla yarı yarıya bölünür', 'Ödeme gecikmeli olduğu için hiçbir yılda'], 'GSYH üretimin yapıldığı dönemi esas alır; ödemenin ne zaman yapıldığı önemli değildir.'),
  ('İşten çıkarmanın çok pahalı olduğu bir işgücü piyasasında firmaların işe alım kararları nasıl etkilenebilir?', 'İleride çıkaramayacakları korkusuyla işe almakta daha temkinli davranırlar', ['İşe alımı sınırsız biçimde artırırlar', 'İşe alım kararları hiç etkilenmez', 'Bütün çalışanlarını hemen işten çıkarırlar ve üretimi tamamen durdururlar'], 'Yüksek çıkarma maliyeti mevcut çalışanları korur, ama firmalar belirsizlikte yeni işçi almaktan kaçınabilir. Bu durum özellikle gençler ve uzun süreli işsizler için girişi zorlaştırabilir.'),
  ('Ekonomik büyümenin yoksulluk üzerindeki etkisinin bazı ülkelerde daha güçlü olmasının nedeni olarak en çok hangisi gösterilir?', 'Büyümenin düşük gelirlilerin çalıştığı sektörlerde ve onlara iş yaratan biçimde gerçekleşmesi', ['Büyümenin yalnızca en zengin yüzde 1\'in gelirini artırması', 'Nüfusun hızla artması', 'Büyüme sırasında enflasyonun sıfıra inmesi ve fiyatların hiç değişmemesi'], 'Tarım ve emek yoğun imalat gibi yoksulların yoğun çalıştığı alanlarda yaşanan büyüme, yoksulluğu daha hızlı azaltır; bu, \'yoksul yanlısı büyüme\' olarak adlandırılır.'),
  ('IS-LM modelinde IS eğrisinin negatif eğimli olmasının nedeni hangisidir?', 'Faiz oranı düştükçe yatırım artar ve çarpan yoluyla denge geliri yükselir', ['Faiz oranı düştükçe para arzı azalır', 'Gelir arttıkça vergi oranları sıfıra iner', 'Faiz oranı düştükçe tasarruflar artar, tüketim azalır ve denge geliri düşer'], 'IS eğrisi mal piyasasını dengeleyen faiz-gelir bileşimlerini gösterir. Düşük faiz daha çok yatırım ve dolayısıyla daha yüksek denge geliri demektir.'),
  ('Klasik modelde reel ücretlerin tam esnek olduğu varsayıldığında emek piyasasında hangi sonuç ortaya çıkar?', 'Emek arzı ile emek talebi eşitlenir ve gönülsüz işsizlik oluşmaz', ['Kalıcı ve yüksek gönülsüz işsizlik oluşur', 'Ücretler sürekli sıfıra iner', 'Emek talebi her zaman emek arzının iki katı olur ve açık işler hiç dolmaz'], 'Ücret, emek piyasasında arz ve talebi eşitleyecek biçimde ayarlanır; bu ücrette çalışmak isteyen herkes iş bulur. Kalan işsizlik gönüllü ya da friksiyoneldir.'),
  ('ILO\'nun \'referans haftasında en az bir saat çalışan istihdamdadır\' tanımına yöneltilen eleştirilerden biri hangisidir?', 'Çok az saat çalışanları istihdamda sayarak işgücü piyasasındaki sıkıntıyı olduğundan hafif gösterebilmesi', ['Tam zamanlı çalışanları işsiz sayması', 'İşsizleri hiç saymaması', 'Yalnızca kamu çalışanlarını ölçmesi ve özel sektörü dışarıda bırakması'], 'Haftada birkaç saat çalışıp daha fazla çalışmak isteyen kişi istihdamda görünür. Bu yüzden eksik istihdam ve atıl işgücü gibi tamamlayıcı göstergeler de izlenir.'),
  ('Bir ekonomide üretim uzun süre potansiyelin üzerinde kalırsa kısa dönemde aşağıdakilerden hangisinin gözlenmesi beklenmez?', 'Fabrikalarda kapasite kullanımının düşmesi', ['Ücretlerin hızla artması', 'Fiyat artışlarının hızlanması', 'İşsizlik oranının doğal oranın altına inmesi'], 'Potansiyel üzerinde üretim, kaynakların olağandan yoğun kullanılması demektir; kapasite kullanımı düşmez, yükselir. Diğer üç gelişme ise aşırı ısınmanın tipik belirtileridir.'),
  ('Kapalı ve devletsiz bir ekonomide tüketim fonksiyonu C = 40 + 0,75Y ve planlanan yatırım 60 milyar liradır. Planlanan yatırım 20 milyar lira artarsa yeni denge geliri kaç milyar lira olur?', '480', ['400', '420', '500'], 'Başlangıç dengesi Y = (40 + 60) / 0,25 = 400\'dür. Çarpan 4 olduğundan 20 milyar liralık artış geliri 80 artırır; yeni denge 480 milyar liradır.'),
  ('Klasik iktisatçılara göre bir ekonomide tasarrufların artması uzun dönemde hangi sonucu doğurur?', 'Faizler düşer, yatırımlar artar ve büyüme desteklenir', ['Toplam talep çöker ve kalıcı işsizlik oluşur', 'Faizler yükselir ve yatırımlar durur', 'Hiçbir değişiklik olmaz, çünkü tasarruf ekonomiyi etkilemez'], 'Klasik görüşte artan tasarruf ödünç verilebilir fonların arzını artırır; faiz düşer ve yatırım aynı ölçüde artar. Keynes ise kısa dönemde bunun talebi düşürebileceğini savunmuştur.'),
  ('Bir resesyon sırasında üretimin düştüğü ancak işsizliğin görece az arttığı bir ülkede bunun olası nedeni hangisidir?', 'Firmaların işçi çıkarmak yerine çalışma saatlerini ve verimliliği düşürmesi', ['İşsizliğin hiçbir zaman ölçülmemesi', 'Resesyonun yalnızca fiyatları etkilemesi', 'Bütün işçilerin aynı anda emekli olması ve işgücünden tamamen çıkması'], 'Deneyimli çalışanları kaybetmek istemeyen firmalar emeği elde tutabilir (emek istifçiliği). Bu durumda üretim düşüşü işsizlikten çok çalışan başına üretimin azalmasına yansır.'),
  ('Bir ekonomide aynı yıl içinde hem enflasyonun hem de işsizliğin hızla düşmesi, aşağıdaki şoklardan hangisiyle en iyi açıklanır?', 'Olumlu bir arz şoku', ['Olumsuz bir talep şoku', 'Olumsuz bir arz şoku', 'Olumlu bir talep şoku'], 'Talep şokları enflasyon ile işsizliği ters yönde hareket ettirir. Her ikisinin birlikte düşmesi, maliyetlerin azaldığı ve üretimin arttığı olumlu bir arz şokunun işaretidir.'),
  ('Bir ülkenin GSYH\'si bir çeyrekte önceki çeyreğe göre yüzde 0,5 azalmış, ama geçen yılın aynı çeyreğine göre yüzde 2 artmıştır. Bu iki bilgi birlikte en doğru nasıl yorumlanır?', 'Yıllık bazda büyüme sürse de ekonomi son çeyrekte yavaşlamaya, hatta küçülmeye başlamıştır', ['Ekonomi kesinlikle hızla büyümektedir', 'Verilerden biri mutlaka hatalıdır', 'Ekonomi bir yıldır sürekli küçülmektedir ve yıllık veri bu nedenle yanlıştır'], 'Yıllık karşılaştırma son dört çeyreğin birikimli etkisini, çeyreklik karşılaştırma ise en son eğilimi gösterir. Çeyreklik düşüş, dönüm noktasının erken bir işareti olabilir.'),
  ('Bir ülkede verimlilik artışı olmadan ücretlerin sürekli hızla artması, toplam arz-toplam talep modeline göre orta vadede hangi riski doğurur?', 'Maliyet artışıyla fiyatların yükselmesi ve istihdamın zayıflaması', ['Fiyatların kesin olarak düşmesi', 'Üretimin kalıcı olarak ikiye katlanması', 'İşsizliğin kesin olarak sıfıra inmesi ve enflasyonun bitmesi'], 'Verimliliği aşan ücret artışı birim maliyetleri yükseltir; kısa dönem arz sola kayar ve fiyatlar artarken üretim ve istihdam baskı altına girer.'),
  ('Bir ülkenin büyüme performansını değerlendirirken tek bir yılın büyüme oranı yerine birkaç yılın ortalamasına bakmak neden daha sağlıklıdır?', 'Tek yılın verisi geçici şoklardan ve baz etkisinden çok etkilenebildiği için', ['Ortalama her zaman daha yüksek çıktığı için', 'Büyüme oranlarının yalnızca nominal olarak hesaplanabilmesi', 'Tek yıllık veriler hiçbir ülkede yayımlanmadığı ve yalnızca on yıllık ortalamalar bilindiği için'], 'Kötü bir hasat ya da derin bir kriz sonrasındaki toparlanma tek bir yılı çarpıtabilir; ortalamalar uzun dönem eğilimi daha iyi gösterir.'),
  ('Okun yasası için aşağıdaki ifadelerden hangisi en doğrudur?', 'Katsayısı ülkeden ülkeye ve dönemden döneme değişen ampirik bir düzenliliktir', ['Bütün ülkelerde aynı katsayıyla geçerli bir doğa yasasıdır', 'Yalnızca 19. yüzyıl İngiltere\'sinde geçerli olmuş tarihsel bir gözlemdir', 'Enflasyon ile faiz arasındaki ilişkiyi açıklayan ve hiç değişmeyen bir teoremdir'], 'Okun\'un \'yasası\' fizik yasası gibi değil, veriden elde edilmiş bir genellemedir; işgücü piyasası kurumları ve verimlilik eğilimleri katsayıyı değiştirir.'),
  ('Solow modelinde diğer her şey aynıyken sermayenin aşınma (amortisman) oranının yükselmesi durağan durumdaki işçi başına sermayeyi nasıl etkiler?', 'Azaltır', ['Artırır', 'Etkilemez', 'Sonsuza kadar artırır ve durağan durumu ortadan kaldırır'], 'Daha yüksek amortisman, mevcut sermayeyi korumak için daha fazla yatırım gerektirir; aynı tasarruf oranıyla daha düşük bir sermaye düzeyinde dengeye ulaşılır.'),
  ('İşgücüne katılma oranı yüzde 55, işsizlik oranı yüzde 20 olan bir ülkede istihdam oranı (istihdamın çalışma çağındaki nüfusa oranı) yüzde kaçtır?', '44', ['35', '11', '75'], 'İstihdam oranı = katılma oranı × (1 − işsizlik oranı) = 0,55 × 0,80 = 0,44, yani yüzde 44\'tür.'),
  ('Bir ekonomik modelde değeri modelin içinde çözülen değişkenlere ne ad verilir?', 'İçsel değişkenler', ['Dışsal değişkenler', 'Sabit parametreler', 'Kukla değişkenler'], 'Örneğin basit Keynesyen modelde denge geliri içsel, otonom yatırım ise dışarıdan verildiği için dışsal değişkendir.'),
  ('Belirli bir tarihteki işsiz kişi sayısı ile bir ay içinde işini kaybedenlerin sayısı arasındaki fark hangi kavram çiftiyle açıklanır?', 'Birincisi stok, ikincisi akım değişkenidir', ['Birincisi akım, ikincisi stok değişkenidir', 'İkisi de stok değişkenidir', 'İkisi de nominal değişkendir ve fiyatlarla ölçülür'], 'İşsiz sayısı belli bir andaki durumu (stok), işini kaybedenler ise bir dönem boyunca gerçekleşen hareketi (akım) gösterir. İşsizlik stoku, giriş ve çıkış akımlarına göre değişir.'),
  ('Bir ülkede ortalama işsizlik süresinin uzaması, aynı işsizlik oranında bile neden daha ciddi bir sorun olarak değerlendirilir?', 'İşsizlerin beceri kaybetme ve kalıcı olarak dışlanma riski arttığı için', ['İşsizlik oranı otomatik olarak sıfıra indiği için', 'Uzun süreli işsizliğin hiçbir maliyeti olmadığı için', 'İşsizlerin daha çok vergi ödediği ve kamu gelirlerini artırdığı için'], 'Aynı oran, kısa süreli çok sayıda iş değişikliğinden ya da az sayıda kişinin çok uzun süre işsiz kalmasından oluşabilir. İkinci durum yapısal ve toplumsal açıdan daha ağırdır.'),
  ('Ekonomik modellerde \'dışsal değişken\' olarak ele alınan bir büyüklük için hangisi doğrudur?', 'Değeri modelin dışında belirlenir ve modele veri olarak girer', ['Değeri modelin içinde çözülür', 'Hiçbir zaman değişmez', 'Yalnızca dış ticaretle ilgili değişkenleri kapsar ve iç ekonomiyi hiç içermez'], 'Dışsal değişkenler modelin açıklamaya çalışmadığı, verili kabul ettiği büyüklüklerdir; bunlardaki değişimin içsel değişkenleri nasıl etkilediği incelenir.'),
  ('Bir gıda firmasının ürünlerini tanıtmak için bir reklam ajansına ödediği bedel GSYH hesabında nasıl ele alınır?', 'Firmanın ara tüketimidir; ayrıca nihai harcama olarak eklenmez', ['Hanehalkı tüketimi olarak GSYH\'ye eklenir', 'Kamu harcaması olarak eklenir', 'Yatırım olarak iki kez sayılır ve GSYH\'yi büyütür'], 'Reklam hizmeti, firmanın satacağı ürünün üretim maliyetine giren bir ara girdidir. Değeri ürünün nihai fiyatına yansıdığından ayrıca eklenmesi çift sayım olur.'),
  ('Avrupa ülkelerinin doğal işsizlik oranlarının ABD\'ye göre uzun süre daha yüksek olmasının açıklamaları arasında aşağıdakilerden hangisi yer alır?', 'Daha cömert işsizlik ödenekleri ve daha katı iş güvencesi kuralları', ['Avrupa\'da hiç sendika bulunmaması', 'Avrupa\'da işsizliğin hiç ölçülmemesi', 'Avrupa\'da çalışma çağındaki nüfusun bulunmaması ve tüm halkın emekli olması'], 'Doğal oran, arama süresini ve işe alım-çıkarma kararlarını etkileyen kurumlara bağlıdır. Uzun süreli ödenekler ve yüksek çıkarma maliyetleri işsizlik süresini uzatabilir.'),
  ('Bir ekonomist, ekonominin aynı yıl içinde hem büyüdüğünü hem de işsizliğin arttığını gözlemliyor. Bu durumun en olası açıklaması hangisidir?', 'Büyüme hızının, işgücü ve verimlilik artışının belirlediği potansiyel büyümenin altında kalması', ['İşsizlik istatistiklerinin kesinlikle yanlış olması', 'Ekonominin aşırı ısınması', 'Nüfusun hızla azalması ve işgücünün küçülmesi'], 'Okun yasasına göre işsizliği sabit tutmak için ekonominin potansiyel hızında büyümesi gerekir; daha yavaş büyüme işsizliği artırabilir.'),
  ('Basit Keynesyen modelde planlanan yatırımın, gelir düzeyinden bağımsız olarak verili kabul edilmesine ne ad verilir?', 'Otonom yatırım', ['Uyarılmış yatırım', 'Net yatırım', 'Stok yatırımı'], 'Otonom yatırım gelire bağlı değildir ve modelde dışarıdan verilir. Gelir arttıkça artan yatırıma ise uyarılmış (türetilmiş) yatırım denir.'),
  ('İktisatçıların \'uyarılmış tüketim\' dediği kavram hangisidir?', 'Gelirdeki değişmeye bağlı olarak değişen tüketim', ['Gelir sıfırken yapılan tüketim', 'Devletin yaptığı tüketim', 'Reklamla yaratılan ve hiç gelire bağlı olmayan tüketim'], 'C = a + bY fonksiyonunda bY terimi uyarılmış tüketimdir ve gelir arttıkça artar; a ise otonom tüketimdir.'),
  ('Bir ülkede GSYH bir yılda yüzde 4 büyümüştür. Tüketim, yatırım ve kamu harcamalarından oluşan yurt içi talebin büyümeye katkısı 5 puandır. Stok değişimi yoksa net ihracatın büyümeye katkısı kaç puandır?', '−1', ['1', '9', '−5'], 'Büyüme, bileşenlerin katkılarının toplamıdır: 4 = 5 + NX katkısı. Buradan net ihracatın katkısı −1 puan bulunur; yani dış talep büyümeyi aşağı çekmiştir.'),
  ('Büyümenin ağırlıklı olarak yatırım harcamalarından kaynaklanmasının, ağırlıklı olarak tüketimden kaynaklanmasına göre daha sürdürülebilir görülmesinin temel nedeni nedir?', 'Yatırımın gelecekteki üretim kapasitesini de artırması', ['Yatırımın hiçbir zaman ithalat gerektirmemesi', 'Tüketimin GSYH\'ye hiç dâhil edilmemesi', 'Yatırım harcamalarının fiyatları her zaman düşürmesi ve enflasyonu bitirmesi'], 'Tüketim bugünkü talebi karşılar; yatırım ise makine, altyapı ve teknolojiyle yarının üretim olanaklarını genişletir.'),
  ('İnsanlar arasındaki güvenin ve işbirliği ağlarının güçlü olduğu toplumlarda ekonomik faaliyetin daha kolay gelişmesi hangi kavramla açıklanır?', 'Sosyal sermaye', ['Fiziki sermaye', 'Finansal sermaye', 'Doğal sermaye'], 'Güven ve ortak normlar, sözleşmelerin uygulanması ve iş birliği için gereken maliyetleri azaltır; bu da yatırımı ve ticareti kolaylaştırır.'),
  ('Almanya\'da okul eğitimini işyerinde çıraklıkla birleştiren \'ikili mesleki eğitim sistemi\', genç işsizliği açısından neden örnek gösterilir?', 'Gençlerin okuldan işe geçişini kolaylaştırarak genç işsizliğini düşük tutmaya yardım ettiği için', ['Gençlerin çalışmasını yasakladığı için', 'Mesleki eğitimi tamamen kaldırıp yalnızca üniversiteyi zorunlu tuttuğu için', 'Bütün gençleri kamu sektöründe istihdam ettiği ve özel sektörde çalışmalarını yasakladığı için'], 'Öğrenciler eğitimleri sırasında işverenlerin ihtiyaç duyduğu becerileri kazanır ve çoğu zaman eğitim aldıkları firmada işe başlar; bu da deneyimsizlik sorununu azaltır.'),
  ('Bir ekonomik zaman serisi genellikle hangi bileşenlere ayrıştırılarak incelenir?', 'Eğilim (trend), konjonktürel, mevsimsel ve düzensiz bileşenler', ['Ücret, rant, faiz ve kâr', 'Tüketim, yatırım, kamu harcaması ve net ihracat bileşenleri ile bunların büyümeye katkıları', 'Emek, sermaye, toprak ve girişimci'], 'Uzun dönem eğilim büyümeyi, konjonktürel bileşen birkaç yıllık dalgalanmaları, mevsimsel bileşen yıl içi tekrarlanan hareketleri, düzensiz bileşen ise rassal şokları yansıtır.'),
  ('Emek verimliliği (işçi başına üretim) ile toplam faktör verimliliği arasındaki fark en doğru nasıl açıklanır?', 'Emek verimliliği sermaye artışıyla da yükselir; toplam faktör verimliliği girdilerin birlikte etkin kullanımını ölçer', ['İkisi aynı kavramın farklı adlarıdır', 'Toplam faktör verimliliği yalnızca tarımda, emek verimliliği yalnızca sanayide ölçülür', 'Emek verimliliği her zaman sabittir, yalnızca toplam faktör verimliliği değişir'], 'İşçilere daha fazla makine verilirse işçi başına üretim artar ama bu artış sermaye derinleşmesinden kaynaklanır. Toplam faktör verimliliği ise girdi artışıyla açıklanamayan etkinlik artışını gösterir.'),
  ('Kişi başı gelir düzeyi aynı olan iki ülkeden biri madencilik ihracatına, diğeri çeşitlendirilmiş bir sanayi ve hizmet yapısına dayanıyor. Uzun dönem büyüme istikrarı açısından hangisi genellikle daha avantajlı kabul edilir?', 'Çeşitlendirilmiş yapıya sahip ülke', ['Yalnızca madene dayanan ülke', 'İkisi her koşulda tamamen aynıdır', 'Hangisinin daha kalabalık olduğuna bakılarak karar verilir'], 'Tek bir emtiaya bağımlı ekonomiler fiyat şoklarına karşı kırılgandır; çeşitlendirilmiş ekonomiler şokları daha iyi dağıtır ve verimlilik artışı için daha çok kaynağa sahiptir.'),
  ('Türkiye\'de imalat sanayi firmalarının yöneticilerine yapılan anketle hesaplanan Reel Kesim Güven Endeksi\'ni hangi kurum yayımlar?', 'Türkiye Cumhuriyet Merkez Bankası', ['Türkiye İstatistik Kurumu', 'Ticaret Bakanlığı', 'Türkiye Odalar ve Borsalar Birliği'], 'Reel Kesim Güven Endeksi, TCMB\'nin İktisadi Yönelim Anketi sonuçlarından derlenir ve imalat sanayinin genel gidişata ilişkin beklentilerini yansıtır.'),
  ('Petrol ithal eden bir ülke için dünya petrol fiyatlarının kalıcı olarak yükselmesi, ülkenin reel geliri üzerinde hangi etkiyi yapar?', 'Aynı miktarda petrol için daha fazla ödeme yapılacağından reel geliri azaltır', ['Reel geliri kesin olarak artırır', 'Hiçbir etkisi olmaz, çünkü petrol yalnızca ulaşımda kullanılır', 'Yalnızca petrol ihraç eden ülkelerin reel gelirini düşürür, ithalatçıları hiç etkilemez'], 'İthal edilen enerjinin pahalanması, ülkenin ürettiği malların daha büyük bir kısmının aynı enerji için yurt dışına aktarılması demektir; bu da ulusal reel geliri azaltır.'),
  ('Yurt içi tasarrufları düşük olan bir ülke, yüksek yatırım oranını uzun süre nasıl finanse edebilir?', 'Yurt dışından borçlanarak ya da yabancı sermaye çekerek', ['Yalnızca daha çok tüketerek', 'İthalatı tamamen keserek', 'Yatırım yapmayı bırakarak ve stok biriktirerek'], 'Ulusal hesap kimliğine göre yatırımın yurt içi tasarrufu aşan kısmı dış tasarrufla, yani cari açık vererek karşılanır; bu da dış finansmana bağımlılık yaratır.'),
  ('Hangi gösterge, bir ülkenin GSYH\'sinin yaşayanların refahını ne ölçüde yansıttığını anlamak için kişi başı GSYH\'ye ek olarak en yararlı bilgiyi sağlar?', 'Medyan hanehalkı kullanılabilir geliri', ['Toplam ihracat hacmi', 'Döviz rezervleri', 'Borsa endeksinin düzeyi'], 'Medyan kullanılabilir gelir, tipik bir hanenin vergiler ve transferler sonrası elinde kalan geliri gösterir; ortalamayı şişiren uç değerlerden etkilenmez.'),
  ('Bir ülkede kadınların ev içinde yaptığı karşılıksız bakım ve ev işlerinin piyasaya aktarılması (örneğin bakıcı ya da kreş hizmeti satın alınması) ölçülen GSYH\'yi nasıl etkiler?', 'Artırır; aynı hizmet artık piyasada alınıp satıldığı için', ['Azaltır; ev işleri GSYH\'den düşülür', 'Hiç etkilemez', 'GSYH\'yi önce artırır sonra aynı tutarda azaltır'], 'Aynı hizmet evde karşılıksız yapıldığında GSYH\'ye girmez; piyasadan satın alındığında girer. Bu nedenle GSYH artışı, toplam üretimdeki gerçek artışı abartabilir.'),
  ('Talep yönlü bir genişlemede kısa dönemde hem üretimin hem de fiyat düzeyinin artması, toplam arz eğrisinin hangi özelliğinden kaynaklanır?', 'Kısa dönem toplam arz eğrisinin pozitif eğimli olmasından', ['Uzun dönem toplam arz eğrisinin yatay olmasından', 'Toplam talep eğrisinin pozitif eğimli olmasından', 'Toplam arz eğrisinin her zaman negatif eğimli olmasından'], 'Talep sağa kaydığında pozitif eğimli kısa dönem arz eğrisi boyunca daha yüksek fiyat ve daha yüksek üretim birlikte gerçekleşir.'),
  ('ABD\'de NBER bir resesyonun başladığını genellikle ne zaman ilan eder?', 'Yeterli veri biriktikten sonra, çoğu zaman resesyon başladıktan aylar sonra geriye dönük olarak', ['Resesyon başlamadan bir yıl önce', 'Her yılın ilk günü düzenli olarak', 'Borsa bir günde yüzde 5 düştüğü anda ve aynı gün içinde'], 'NBER kesinliği hıza tercih eder; verilerin revizyonlarını bekler. Örneğin Aralık 2007\'de başlayan resesyonun tepe tarihi ancak Aralık 2008\'de açıklanmıştır.'),
  ('Hanehalklarının yüksek borç yüküyle girdiği bir dönemde konut fiyatlarının düşmesi, toplam talep üzerinde neden özellikle güçlü bir etki yaratabilir?', 'Haneler borçlarını azaltmak için harcamalarını sert biçimde kısmak zorunda kalır', ['Haneler borçlarını unutup harcamalarını artırır', 'Borçlu haneler otomatik olarak daha çok gelir elde eder', 'Konut fiyatlarının tüketimle hiçbir ilgisi yoktur ve haneler harcamalarını değiştirmez'], 'Varlık değeri düşerken borcun nominal tutarı aynı kalır. Bilançosu bozulan haneler tasarruf ederek borç ödemeye yönelir ve tüketim talebi uzun süre zayıf kalır.'),
  ('Bir ülkenin GSYH\'si artarken sera gazı salımlarının azalmasına ne ad verilir?', 'Mutlak ayrışma', ['Stagflasyon', 'Hollanda hastalığı', 'Çevresel Kuznets tuzağı ve ters ayrışma'], 'Ayrışma, ekonomik büyümenin çevresel baskıdan kopmasıdır. Salımlar büyümeden yavaş artıyorsa göreli, mutlak olarak azalıyorsa mutlak ayrışmadan söz edilir.'),
  ('Keynesyen yaklaşımda \'kısa dönemde üretimi belirleyen esas olarak taleptir\' görüşü hangi varsayıma dayanır?', 'Ekonomide atıl kapasite ve işsiz kaynakların bulunması', ['Ekonominin her zaman tam kapasiteyle çalışması', 'Fiyatların ve ücretlerin anında uyum sağlaması', 'Tasarrufların her zaman yatırımlara faizle eşitlenmesi'], 'Atıl kaynaklar varken firmalar satabildikleri kadar üretir; bu yüzden harcamadaki değişmeler üretimi doğrudan etkiler. Tam kapasitede ise talep artışı fiyatlara yansır.'),
  ('Bir ülkede ücretli çalışanların toplam istihdam içindeki payının zamanla artması, genellikle hangi yapısal değişimin işaretidir?', 'Tarım ve küçük aile işletmelerinden modern sanayi ve hizmet sektörlerine geçiş', ['Ekonominin sanayisizleşip tarıma dönmesi', 'İşsizliğin tamamen ortadan kalkması', 'Kayıt dışı istihdamın sürekli artması ve sigortalılığın azalması'], 'Kalkınmayla birlikte kendi hesabına çalışan çiftçi ve ücretsiz aile işçisi oranı düşer, firmalarda ücretle çalışanların payı yükselir.'),
  ('Bir resesyon sonrasında toparlanmanın \'K\' harfiyle tanımlanması ne anlama gelir?', 'Bazı sektörlerin ve gelir gruplarının hızla toparlanırken diğerlerinin gerilemeyi sürdürmesi', ['Ekonominin iki kez üst üste daraldığı', 'Ekonominin hiç toparlanmadığı', 'Bütün sektörlerin aynı hızda ve aynı anda toparlandığı, gelir farklarının ise kapandığı'], 'K harfinin yukarı ve aşağı uzanan iki kolu, toparlanmanın eşitsiz olduğunu simgeler; terim özellikle COVID-19 sonrasında yaygınlaşmıştır.'),
  ('Bir ekonomide resesyon sırasında üretim yüzde 4 düşmüş, istihdam ise yalnızca yüzde 1 azalmıştır. Bu dönemde işçi başına emek verimliliği yaklaşık nasıl değişmiştir?', 'Yaklaşık yüzde 3 azalmıştır', ['Yaklaşık yüzde 3 artmıştır', 'Yaklaşık yüzde 5 artmıştır', 'Değişmemiştir'], 'İşçi başına verimlilik değişimi ≈ üretim değişimi − istihdam değişimi = −4 − (−1) = −3. Firmaların işçileri elde tutması verimliliği resesyonda düşürür.'),
  ('Bir ekonomide toplam talebin bileşenlerinden en istikrarlı olanının genellikle kamu tüketim harcamaları olmasının nedeni hangisidir?', 'Maaş ve hizmet giderlerinin bütçeyle önceden belirlenmesi ve konjonktüre göre hızla değişmemesi', ['Kamu harcamalarının GSYH\'ye dâhil edilmemesi', 'Kamu tüketiminin her yıl tam olarak sıfır olması', 'Kamu harcamalarının yalnızca resesyonlarda yapılması'], 'Eğitim, sağlık ve güvenlik gibi kamu hizmetleri sürekli sunulur; özel yatırım ve dayanıklı mal tüketimi gibi beklentilere bağlı kalemler ise çok daha oynaktır.'),
  ('Bir yıl içinde bir kentteki mevcut konutların piyasa değerinin yüzde 30 artması o yılın GSYH\'sini doğrudan nasıl etkiler?', 'Doğrudan etkilemez; mevcut varlıkların değer artışı yeni üretim değildir', ['GSYH\'yi konut değerindeki artış kadar artırır', 'Yalnızca ithalat kalemini değiştirir', 'GSYH\'yi aynı tutarda azaltır, çünkü konut sahipleri daha az harcar'], 'GSYH dönem içinde üretilen mal ve hizmetleri ölçer. Var olan konutların fiyatının yükselmesi bir servet değişimidir; yeni konut inşaatı ise yatırım olarak GSYH\'ye girer.'),
  ('Hizmet sektörlerinde verimlilik ölçümünün sanayiye göre daha zor olmasının temel nedeni hangisidir?', 'Hizmetlerin miktarını ve kalitesini fiziksel birimlerle tanımlamanın güç olması', ['Hizmet sektöründe hiç çalışan bulunmaması', 'Hizmetlerin GSYH\'ye hiç girmemesi', 'Hizmet fiyatlarının hiçbir zaman değişmemesi ve sabit kalması'], 'Bir fabrikanın ürettiği ton çelik kolayca sayılır; bir doktorun ya da öğretmenin ürettiği hizmetin miktarı ve kalitesi ise ölçülmesi çok daha güç bir çıktıdır.'),
  ('TÜİK bir çeyreğe ait GSYH\'nin ilk tahminini genellikle çeyrek bittikten ne kadar süre sonra açıklar?', 'Yaklaşık iki ay sonra', ['Ertesi gün', 'Yaklaşık bir hafta sonra', 'Yaklaşık iki yıl sonra'], 'Çeyreklik GSYH, gerekli verilerin derlenmesi için çeyrek sonundan yaklaşık 60 gün sonra yayımlanır; sonraki dönemlerde revize edilebilir.'),
  ('Bir ülkede GSYH artışının büyük bölümü yalnızca birkaç büyük şirketin kârlarından oluşuyor ve ücretler yerinde sayıyorsa, GSYH büyümesinin tipik bir hanenin refahını yansıtması hakkında ne söylenebilir?', 'Büyüme hane gelirlerine sınırlı yansıdığı için refahı olduğundan iyi gösterebilir', ['Her hane geliri GSYH ile aynı oranda artmıştır', 'GSYH büyümesi hiçbir zaman gelir dağılımını etkilemez', 'Ücretlerin sabit kalması GSYH\'nin azaldığını kanıtlar'], 'Toplam üretimin artması, artışın kimlere gittiğini göstermez. Kazançlar dar bir gruba gidiyorsa medyan hane geliri durağan kalabilir.'),
];
